content.text:
@font-face {
  font-family: 'Press Start 2P';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(https://fonts.gstatic.com/s/pressstart2p/v16/e3t4euO8T-267oIAQAu6jDQyK0nS.ttf) format('truetype');
}
@font-face {
  font-family: 'VT323';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(https://fonts.gstatic.com/s/vt323/v18/pxiKyp0ihIEF2hsY.ttf) format('truetype');
}

input.content:
@font-face {
  font-family: 'Press Start 2P';
  src: url('./assets/fonts/PressStart2P.ttf') format('truetype');
  font-display: swap;
}
@font-face {
  font-family: 'VT323';
  src: url('./assets/fonts/VT323.ttf') format('truetype');
  font-display: swap;
}

:root {
  --bg: #050810;
  --bg2: #0a1020;
  --panel: #0d1628;
  --panel2: #111f36;
  --line: #24395e;
  --line-bright: #3f5f96;
  --ink: #e9f1ff;
  --muted: #8ea4c8;
  --yellow: #ffd23f;
  --yellow-deep: #e0a800;
  --green: #31d67f;
  --green-deep: #0c7a3e;
  --blue: #4a8dff;
  --red: #ff5a68;
  --pink: #ff7ac6;
  --pixel: 'Press Start 2P', 'Courier New', monospace;
  --body: 'VT323', 'Courier New', monospace;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
html { background: var(--bg); }
body {
  min-height: 100dvh;
  color: var(--ink);
  font-family: var(--body);
  font-size: 21px;
  line-height: 1.28;
  background:
    radial-gradient(120% 80% at 50% -10%, #14233f 0%, #070c18 55%, #04070e 100%);
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}
button { font: inherit; color: inherit; }
h1, h2, h3, p { margin: 0; }
.hidden { display: none !important; }

#app {
  position: relative;
  width: 100%;
  height: 100dvh;
  max-width: 640px;
  margin: 0 auto;
  overflow: hidden;
  isolation: isolate;
}
@media (min-width: 900px) {
  #app {
    border-left: 2px solid #16233c;
    border-right: 2px solid #16233c;
    box-shadow: 0 0 0 1px #000, 0 0 80px rgba(30, 70, 140, .35);
    background: #070c18;
  }
  body {
    background:
      repeating-linear-gradient(90deg, rgba(255,255,255,.012) 0 1px, transparent 1px 7px),
      radial-gradient(100% 90% at 50% 0%, #14233f 0%, #060a13 60%, #03050a 100%);
  }
}

/* CRT atmosphere */
.crt {
  position: fixed;
  inset: 0;
  z-index: 90;
  pointer-events: none;
  background:
    repeating-linear-gradient(0deg, rgba(0,0,0,.16) 0 1px, transparent 1px 3px);
  mix-blend-mode: multiply;
  opacity: .55;
}
.crt::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(120% 100% at 50% 45%, transparent 55%, rgba(0,0,0,.5) 100%);
}

.screen {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: calc(14px + var(--safe-t)) 16px calc(14px + var(--safe-b));
  overflow: hidden;
}
.eyebrow {
  font-family: var(--pixel);
  font-size: 8px;
  letter-spacing: .16em;
  color: var(--yellow);
  text-transform: uppercase;
  text-shadow: 0 2px 0 #000;
}

/* ---------- buttons ---------- */
.btn {
  position: relative;
  display: block;
  width: 100%;
  padding: 13px 16px;
  font-family: var(--pixel);
  font-size: 10px;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--ink);
  background: linear-gradient(180deg, #1b2c4b, #111d33);
  border: 2px solid var(--line-bright);
  box-shadow: 0 4px 0 #050a14, inset 0 1px 0 rgba(255,255,255,.12);
  cursor: pointer;
  transition: transform .08s, filter .08s, background .15s;
}
.btn:active { transform: translateY(3px); box-shadow: 0 1px 0 #050a14; }
.btn:hover { filter: brightness(1.18); }
.btn:focus-visible { outline: 2px solid var(--yellow); outline-offset: 3px; }
.btn-primary {
  color: #161000;
  background: linear-gradient(180deg, #ffe067, var(--yellow) 55%, #e8ad12);
  border-color: #fff3ad;
  box-shadow: 0 4px 0 #7a5400, inset 0 1px 0 #fffbe0;
  text-shadow: 0 1px 0 rgba(255,255,255,.4);
}
.btn-ghost {
  background: transparent;
  border-color: var(--line);
  color: var(--muted);
  box-shadow: none;
}
.btn-small { width: auto; padding: 9px 12px; font-size: 7px; }
.btn:disabled {
  opacity: .4;
  cursor: not-allowed;
  filter: grayscale(.6);
}
.menu-stack { display: flex; flex-direction: column; gap: 10px; width: 100%; max-width: 330px; margin: 0 auto; }
.icon-btn {
  flex: 0 0 auto;
  width: 38px; height: 38px;
  display: grid; place-items: center;
  font-family: var(--pixel);
  font-size: 12px;
  color: var(--ink);
  background: #101d34;
  border: 2px solid var(--line);
  cursor: pointer;
}
.icon-btn:active { transform: translateY(2px); }

/* ---------- title ---------- */
.title-screen {
  justify-content: flex-start;
  align-items: center;
  text-align: center;
  padding-top: calc(20px + var(--safe-t));
  overflow-y: auto;
}
.title-sun {
  position: absolute;
  left: 50%; top: 42%;
  width: 560px; height: 560px;
  transform: translate(-50%, -50%);
  background: repeating-conic-gradient(from 0deg, rgba(255,210,63,.15) 0deg 9deg, transparent 9deg 18deg);
  border-radius: 50%;
  -webkit-mask-image: radial-gradient(circle, #000 0 32%, transparent 68%);
  mask-image: radial-gradient(circle, #000 0 32%, transparent 68%);
  animation: spin 90s linear infinite;
  z-index: -1;
}
@keyframes spin { to { transform: translate(-50%,-50%) rotate(360deg); } }
.title-crowd {
  position: absolute;
  left: 0; right: 0; bottom: 0;
  height: 28%;
  z-index: -1;
  background:
    radial-gradient(circle at 8% 40%, #1b3358 0 5px, transparent 6px),
    radial-gradient(circle at 17% 55%, #24406b 0 5px, transparent 6px),
    radial-gradient(circle at 27% 35%, #1b3358 0 6px, transparent 7px),
    radial-gradient(circle at 38% 60%, #2a4a7a 0 5px, transparent 6px),
    radial-gradient(circle at 48% 40%, #1b3358 0 6px, transparent 7px),
    radial-gradient(circle at 58% 62%, #24406b 0 5px, transparent 6px),
    radial-gradient(circle at 69% 38%, #1b3358 0 6px, transparent 7px),
    radial-gradient(circle at 79% 58%, #2a4a7a 0 5px, transparent 6px),
    radial-gradient(circle at 90% 42%, #1b3358 0 6px, transparent 7px);
  background-size: 100% 100%;
  opacity: .8;
  border-top: 2px solid rgba(80,120,190,.25);
}
.title-inner {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  margin: auto 0;
  padding: 8px 0 18px;
}
.logo {
  font-family: var(--pixel);
  line-height: 1.18;
  text-transform: uppercase;
  margin: 2px 0 0;
  transform: skewY(-2deg);
}
.logo-line1 {
  display: block;
  font-size: clamp(26px, 8.6vw, 46px);
  color: #fff;
  text-shadow: 0 3px 0 #4a8dff, 0 6px 0 #123b7d, 0 9px 16px rgba(0,0,0,.7);
  letter-spacing: .02em;
}
.logo-line2 {
  display: block;
  font-size: clamp(34px, 11.6vw, 62px);
  color: var(--yellow);
  text-shadow: 0 3px 0 #b57600, 0 6px 0 #6b4300, 0 10px 18px rgba(0,0,0,.75);
  letter-spacing: .01em;
}
.logo-line3 {
  display: block;
  margin-top: 9px;
  font-size: clamp(11px, 3.6vw, 18px);
  color: #cfe2ff;
  letter-spacing: .22em;
  text-shadow: 0 2px 0 #000;
}
.title-hero {
  position: relative;
  width: 150px; height: 168px;
  margin: 4px auto -2px;
  filter: drop-shadow(0 10px 0 rgba(0,0,0,.35));
}
.title-hero canvas {
  width: 100%; height: 100%;
  image-rendering: pixelated;
  animation: heroBob 2.4s ease-in-out infinite;
}
@keyframes heroBob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }
.title-tag {
  font-size: 22px;
  color: #c4d6f2;
  text-shadow: 0 2px 0 #000;
  margin-bottom: 4px;
}
.title-foot {
  margin-top: 14px;
  font-family: var(--pixel);
  font-size: 6px;
  letter-spacing: .12em;
  color: #5f759b;
  line-height: 1.8;
}
.title-screen .eyebrow { margin-top: 2px; }

/* ---------- shared page head ---------- */
.page-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 12px;
  border-bottom: 2px solid var(--line);
  margin-bottom: 12px;
}
.page-head > div { flex: 1; }
.page-head h2 {
  font-family: var(--pixel);
  font-size: 13px;
  line-height: 1.5;
  color: #fff;
  text-shadow: 0 2px 0 #000;
}
.page-head.compact { border-bottom: none; margin-bottom: 0; padding-bottom: 4px; }

/* ---------- map ---------- */
.map-screen { overflow: hidden; }
.map-body { flex: 1; overflow-y: auto; padding-right: 2px; scrollbar-width: thin; scrollbar-color: #2a3f65 transparent; }
.player-card {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 10px;
  background: linear-gradient(135deg, #12203a, #0b1425);
  border: 2px solid var(--line);
  margin-bottom: 14px;
  position: relative;
}
.player-card::before {
  content: "";
  position: absolute; inset: 0;
  background: repeating-linear-gradient(135deg, rgba(255,210,63,.05) 0 6px, transparent 6px 12px);
  pointer-events: none;
}
.player-card canvas { width: 76px; height: 86px; image-rendering: pixelated; flex: 0 0 auto; }
.player-card-main { flex: 1; min-width: 0; }
.player-name {
  font-family: var(--pixel);
  font-size: 10px;
  color: var(--yellow);
  line-height: 1.5;
  text-shadow: 0 2px 0 #000;
}
.player-name .num { color: var(--muted); font-size: 8px; }
.player-pos {
  font-family: var(--pixel);
  font-size: 6px;
  letter-spacing: .1em;
  color: var(--muted);
  margin: 5px 0 8px;
}
.stat-list { display: grid; grid-template-columns: 1fr 1fr; gap: 3px 10px; }
.stat-row { display: flex; align-items: center; gap: 5px; }
.stat-row span { font-family: var(--pixel); font-size: 5px; color: #9db2d6; width: 42px; }
.stat-track { flex: 1; height: 6px; background: #060c16; border: 1px solid #223454; }
.stat-fill { height: 100%; background: linear-gradient(90deg, #1e7a4a, var(--green)); }
.stat-row b { font-family: var(--pixel); font-size: 6px; color: #cfe0ff; width: 14px; text-align: right; }

.chapter-list { display: flex; flex-direction: column; gap: 9px; }
.chapter {
  display: flex;
  align-items: stretch;
  gap: 10px;
  padding: 11px 12px;
  background: #0b1526;
  border: 2px solid #1b2c4a;
  border-left: 4px solid #2a4066;
  cursor: pointer;
  text-align: left;
  transition: border-color .12s, transform .08s, background .12s;
}
.chapter:active { transform: scale(.99); }
.chapter:hover:not(.locked) { border-color: var(--line-bright); background: #0e1b30; }
.chapter.locked { opacity: .45; cursor: not-allowed; }
.chapter.current { border-left-color: var(--yellow); background: linear-gradient(90deg, rgba(255,210,63,.1), #0b1526 45%); }
.chapter.done { border-left-color: var(--green); }
.chapter-num {
  font-family: var(--pixel);
  font-size: 14px;
  color: #58719c;
  align-self: center;
  width: 30px;
  text-align: center;
}
.chapter.current .chapter-num { color: var(--yellow); }
.chapter.done .chapter-num { color: var(--green); }
.chapter-main { flex: 1; min-width: 0; }
.chapter-title {
  font-family: var(--pixel);
  font-size: 8px;
  line-height: 1.6;
  color: #eaf3ff;
}
.chapter-sub { font-size: 18px; color: var(--muted); margin-top: 3px; }
.chapter-state {
  align-self: center;
  font-family: var(--pixel);
  font-size: 6px;
  color: #55709c;
  letter-spacing: .08em;
  white-space: nowrap;
}
.chapter.current .chapter-state { color: var(--yellow); }
.chapter.done .chapter-state { color: var(--green); }
.map-hint {
  margin: 12px 2px 6px;
  font-size: 19px;
  color: #7890b4;
}
.map-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-top: 8px;
  border-top: 1px solid #16233a;
}
.save-note { font-family: var(--pixel); font-size: 5px; color: #4f668b; text-align: right; line-height: 1.8; }

/* ---------- story ---------- */
.story-screen {
  justify-content: flex-end;
  padding-left: 12px; padding-right: 12px;
}
.story-sky {
  position: absolute; inset: 0;
  background: linear-gradient(180deg, #0b1a33 0%, #1d2c4b 38%, #6d3d4e 68%, #b6603d 84%, #2b1b20 100%);
  transition: background 1s;
  z-index: -3;
}
.story-scene { position: absolute; inset: 0; z-index: -2; overflow: hidden; }
.scene-city {
  position: absolute; left: 0; right: 0; bottom: 0; height: 58%;
  background:
    linear-gradient(transparent 0 10%, #0a1120 10%),
    repeating-linear-gradient(90deg, #101a2e 0 18px, transparent 18px 26px, #0c1526 26px 52px, transparent 52px 60px);
  background-size: 100% 100%, 220px 100%;
  opacity: .9;
  -webkit-mask-image: linear-gradient(180deg, transparent, #000 22%);
  mask-image: linear-gradient(180deg, transparent, #000 22%);
}
.scene-city::before {
  content: "";
  position: absolute; inset: 0;
  background:
    repeating-linear-gradient(0deg, transparent 0 14px, rgba(255,210,63,.35) 14px 16px, transparent 16px 30px),
    repeating-linear-gradient(90deg, transparent 0 16px, rgba(255,210,63,.25) 16px 18px, transparent 18px 34px);
  background-size: 34px 30px, 34px 30px;
  opacity: .35;
  -webkit-mask-image: linear-gradient(180deg, transparent 20%, #000 70%);
  mask-image: linear-gradient(180deg, transparent 20%, #000 70%);
}
.scene-pitch {
  position: absolute; left: -10%; right: -10%; bottom: -20%; height: 42%;
  background: repeating-linear-gradient(100deg, #0f4a2d 0 34px, #0d4027 34px 68px);
  transform: perspective(300px) rotateX(58deg);
  transform-origin: bottom;
  opacity: .65;
}
.scene-glow {
  position: absolute; inset: 0;
  background:
    radial-gradient(50% 40% at 20% 70%, rgba(255,180,80,.28), transparent 70%),
    radial-gradient(40% 30% at 82% 24%, rgba(90,150,255,.25), transparent 70%);
  animation: glowPulse 6s ease-in-out infinite;
}
@keyframes glowPulse { 0%,100% { opacity: .7; } 50% { opacity: 1; } }
.chapter-card {
  position: absolute;
  left: 0; right: 0; top: 30%;
  text-align: center;
  padding: 22px 20px;
  background: rgba(4,8,16,.72);
  border-top: 2px solid var(--yellow);
  border-bottom: 2px solid var(--yellow);
  animation: cardIn .5s ease-out both;
  z-index: 5;
}
@keyframes cardIn { from { opacity: 0; transform: scaleY(.7); } to { opacity: 1; transform: scaleY(1); } }
.chapter-card h2 {
  font-family: var(--pixel);
  font-size: clamp(12px, 4.2vw, 19px);
  line-height: 1.7;
  margin: 12px 0 10px;
  color: #fff;
  text-shadow: 0 3px 0 #000, 0 0 24px rgba(255,210,63,.45);
}
.chapter-card p:last-child {
  font-family: var(--pixel);
  font-size: 7px;
  letter-spacing: .18em;
  color: var(--muted);
}
.skip-btn {
  position: absolute;
  top: calc(10px + var(--safe-t)); right: 12px;
  font-family: var(--pixel);
  font-size: 6px;
  letter-spacing: .1em;
  color: #7f95b9;
  background: rgba(5,10,20,.7);
  border: 1px solid #2a3d5e;
  padding: 7px 9px;
  cursor: pointer;
  z-index: 6;
}
.dialogue-box {
  position: relative;
  display: flex;
  gap: 12px;
  width: 100%;
  min-height: 148px;
  padding: 12px;
  background: linear-gradient(180deg, rgba(12,22,40,.97), rgba(6,12,24,.98));
  border: 3px solid #d8e6ff;
  box-shadow: 0 0 0 3px #0a1322, 0 0 0 5px #3a5379, 0 12px 30px rgba(0,0,0,.6);
  margin-bottom: 2px;
  z-index: 4;
}
.portrait-frame {
  flex: 0 0 auto;
  width: 84px; height: 96px;
  background:
    repeating-linear-gradient(45deg, rgba(255,255,255,.04) 0 4px, transparent 4px 8px),
    radial-gradient(circle at 50% 35%, #2a4066, #101a2e 70%);
  border: 2px solid #3a5379;
  display: grid; place-items: center;
  overflow: hidden;
}
.portrait-frame.narrator { opacity: .25; }
.portrait-frame canvas { width: 72px; height: 81px; image-rendering: pixelated; }
.dialogue-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.speaker {
  display: inline-block;
  align-self: flex-start;
  font-family: var(--pixel);
  font-size: 8px;
  letter-spacing: .05em;
  color: #161000;
  background: var(--yellow);
  padding: 5px 7px 4px;
  margin-bottom: 8px;
  box-shadow: 0 2px 0 #7a5400;
}
.dialogue-main p {
  font-size: 23px;
  line-height: 1.25;
  color: #e7f0ff;
  text-shadow: 0 1px 0 #000;
  flex: 1;
}
.next-cue {
  align-self: flex-end;
  color: var(--yellow);
  font-size: 14px;
  animation: blink 1s steps(2) infinite;
}
@keyframes blink { 50% { opacity: 0; } }

/* ---------- training ---------- */
.training-screen { justify-content: flex-start; overflow-y: auto; }
.training-lead { font-size: 23px; color: #b9cceb; margin: 10px 2px 16px; }
.training-list { display: flex; flex-direction: column; gap: 10px; }
.training-card {
  text-align: left;
  padding: 14px;
  background: linear-gradient(135deg, #101f38, #0a1322);
  border: 2px solid var(--line);
  border-left: 4px solid var(--yellow);
  cursor: pointer;
  transition: transform .08s, border-color .12s, background .12s;
}
.training-card:hover { border-color: var(--line-bright); background: linear-gradient(135deg, #142745, #0c1729); }
.training-card:active { transform: scale(.99); }
.training-card h3 {
  font-family: var(--pixel);
  font-size: 9px;
  color: var(--yellow);
  line-height: 1.6;
  margin-bottom: 7px;
}
.training-card p { font-size: 20px; color: #b7c9e7; }
.training-card .gain {
  display: inline-block;
  margin-top: 8px;
  font-family: var(--pixel);
  font-size: 7px;
  color: var(--green);
  background: rgba(49,214,127,.1);
  border: 1px solid rgba(49,214,127,.4);
  padding: 5px 7px;
}
.training-note { margin: 16px 2px; font-size: 18px; color: #6f86aa; text-align: center; }

/* ---------- match ---------- */
.match-screen {
  padding: calc(6px + var(--safe-t)) 8px calc(6px + var(--safe-b));
  gap: 6px;
  overflow: hidden;
}
.hud {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  background: linear-gradient(180deg, #101d33, #0a1424);
  border: 2px solid #2b446d;
  position: relative;
}
.hud-team {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-family: var(--pixel);
  font-size: 7px;
  letter-spacing: .02em;
  color: #dce9ff;
  white-space: nowrap;
  overflow: hidden;
}
.hud-team.right { justify-content: flex-end; }
.hud-swatch { width: 10px; height: 10px; flex: 0 0 auto; border: 1px solid rgba(255,255,255,.6); }
.hud-score { text-align: center; flex: 0 0 auto; padding: 0 8px; }
.scoreline {
  font-family: var(--pixel);
  font-size: 17px;
  color: #fff;
  line-height: 1.3;
  text-shadow: 0 2px 0 #000;
  display: flex; gap: 7px; justify-content: center;
}
.scoreline em { color: var(--yellow); font-style: normal; }
.clockline {
  display: flex; gap: 6px; justify-content: center;
  font-family: var(--pixel);
  font-size: 5px;
  color: #89a3cc;
  letter-spacing: .06em;
  margin-top: 3px;
}
#clock { color: var(--yellow); }
.pause-btn { width: 30px; height: 30px; font-size: 8px; margin-left: 2px; }

.pitch-wrap {
  position: relative;
  flex: 1;
  min-height: 0;
  border: 2px solid #2b446d;
  background: #08111f;
  overflow: hidden;
}
#pitch {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.banner {
  position: absolute;
  left: 50%; top: 42%;
  transform: translate(-50%, -50%);
  padding: 10px 18px;
  background: rgba(4,8,16,.9);
  border-top: 3px solid var(--yellow);
  border-bottom: 3px solid var(--yellow);
  font-family: var(--pixel);
  font-size: 12px;
  color: #fff;
  text-align: center;
  line-height: 1.8;
  text-shadow: 0 2px 0 #000;
  animation: bannerIn .28s ease-out both;
  z-index: 3;
  max-width: 90%;
}
