// ---------------------------------------------------------------------------
// Procedural pixel-art portraits (64 x 72). No external images.
// ---------------------------------------------------------------------------

const W = 64, H = 72;

function ellipse(ctx, cx, cy, rx, ry, color) {
  ctx.fillStyle = color;
  for (let dy = -ry; dy <= ry; dy++) {
    const w = Math.floor(rx * Math.sqrt(Math.max(0, 1 - (dy * dy) / (ry * ry))));
    if (w > 0) ctx.fillRect(Math.round(cx - w), Math.round(cy + dy), w * 2, 1);
  }
}

function circle(ctx, cx, cy, r, color) {
  ellipse(ctx, cx, cy, r, r, color);
}

function shade(hex, amount) {
  const n = parseInt(hex.replace('#', ''), 16);
  const r = Math.max(0, Math.min(255, ((n >> 16) & 255) * amount));
  const g = Math.max(0, Math.min(255, ((n >> 8) & 255) * amount));
  const b = Math.max(0, Math.min(255, (n & 255) * amount));
  return `rgb(${r | 0},${g | 0},${b | 0})`;
}

const DIGITS = {
  0: ['111', '101', '101', '101', '111'],
  1: ['010', '110', '010', '010', '111'],
  2: ['111', '001', '111', '100', '111'],
  3: ['111', '001', '111', '001', '111'],
  4: ['101', '101', '111', '001', '001'],
  5: ['111', '100', '111', '001', '111'],
  6: ['111', '100', '111', '101', '111'],
  7: ['111', '001', '010', '010', '010'],
  8: ['111', '101', '111', '101', '111'],
  9: ['111', '101', '111', '001', '111']
};

function drawNumber(ctx, num, x, y, color, scale = 2) {
  const str = String(num ?? 0);
  ctx.fillStyle = color;
  let ox = x;
  for (const ch of str) {
    const glyph = DIGITS[ch];
    if (glyph) {
      glyph.forEach((row, ry) => {
        [...row].forEach((bit, rx) => {
          if (bit === '1') ctx.fillRect(ox + rx * scale, y + ry * scale, scale, scale);
        });
      });
    }
    ox += 4 * scale;
  }
}

export function drawPortrait(canvas, char = {}, opts = {}) {
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, W, H);

  if (char.narrator) {
    drawNarrator(canvas);
    return;
  }

  const skin = char.skin || '#a96b45';
  const skinDark = shade(skin, 0.76);
  const hairColor = char.hairColor || '#1a1410';
  const hairDark = shade(hairColor, 0.7);
  const jersey = opts.jersey || char.jersey || '#f2c81c';
  const trim = opts.trim || char.trim || '#0c7a3e';
  const shorts = opts.shorts || char.shorts || '#1450a0';
  const style = char.hair || 'short';
  const accessory = char.accessory || 'none';

  // ---- shoulders / jersey ----
  ctx.fillStyle = shade(jersey, 0.8);
  ctx.beginPath();
  ctx.moveTo(3, H); ctx.lineTo(8, 58); ctx.lineTo(20, 51);
  ctx.lineTo(44, 51); ctx.lineTo(56, 58); ctx.lineTo(61, H);
  ctx.closePath(); ctx.fill();

  ctx.fillStyle = jersey;
  ctx.beginPath();
  ctx.moveTo(5, H); ctx.lineTo(10, 59); ctx.lineTo(22, 52);
  ctx.lineTo(42, 52); ctx.lineTo(54, 59); ctx.lineTo(59, H);
  ctx.closePath(); ctx.fill();

  // shoulder trim
  ctx.fillStyle = trim;
  ctx.fillRect(10, 59, 3, 4);
  ctx.fillRect(51, 59, 3, 4);
  ctx.fillRect(20, 52, 24, 2);

  // collar
  ctx.fillStyle = shade(trim, 0.8);
  ctx.fillRect(27, 52, 10, 2);
  ctx.fillStyle = skinDark;
  ctx.fillRect(29, 52, 6, 3);
  ctx.fillStyle = skin;
  ctx.fillRect(30, 52, 4, 2);

  // jersey number
  drawNumber(ctx, opts.number ?? char.number ?? 10, 28, 60, trim, 2);
  ctx.fillStyle = shade(jersey, 1.15);
  ctx.fillRect(16, 64, 6, 1);
  ctx.fillRect(42, 64, 6, 1);

  // ---- neck ----
  ctx.fillStyle = skinDark;
  ctx.fillRect(27, 45, 10, 8);
  ctx.fillStyle = skin;
  ctx.fillRect(28, 45, 8, 7);
  ctx.fillStyle = skinDark;
  ctx.fillRect(28, 50, 8, 2);

  // ---- long hair behind head ----
  if (style === 'long') {
    ctx.fillStyle = hairDark;
    ctx.fillRect(13, 28, 9, 26);
    ctx.fillRect(42, 28, 9, 26);
    ctx.fillStyle = hairColor;
    ctx.fillRect(14, 29, 7, 24);
    ctx.fillRect(43, 29, 7, 24);
  }

  // ---- head ----
  ellipse(ctx, 32, 33, 16, 18, hairDark);
  ellipse(ctx, 32, 33, 15, 17, skinDark);
  ellipse(ctx, 32, 32, 14, 16, skin);

  // ears
  ctx.fillStyle = skinDark;
  ctx.fillRect(17, 31, 3, 8);
  ctx.fillRect(44, 31, 3, 8);
  ctx.fillStyle = skin;
  ctx.fillRect(18, 32, 2, 5);
  ctx.fillRect(44, 32, 2, 5);

  // cheek shading
  ctx.fillStyle = skinDark;
  ctx.fillRect(20, 39, 2, 4);
  ctx.fillRect(42, 39, 2, 4);
  ctx.fillStyle = shade(skin, 1.08);
  ctx.fillRect(24, 27, 3, 6);
  ctx.fillRect(27, 25, 3, 4);

  // ---- hair ----
  if (style === 'spiky') {
    ctx.fillStyle = hairDark;
    const spikes = [
      [[12, 22], [18, 3], [23, 20]],
      [[19, 18], [27, 0], [31, 17]],
      [[27, 16], [34, 1], [38, 17]],
      [[35, 18], [44, 4], [46, 21]],
      [[42, 21], [52, 9], [50, 26]]
    ];
    for (const tri of spikes) {
      ctx.beginPath();
      ctx.moveTo(tri[0][0], tri[0][1]);
      ctx.lineTo(tri[1][0], tri[1][1]);
      ctx.lineTo(tri[2][0], tri[2][1]);
      ctx.closePath();
      ctx.fill();
    }
    ctx.fillStyle = hairColor;
    ellipse(ctx, 32, 25, 16, 12, hairColor);
    ctx.fillStyle = hairDark;
    ctx.fillRect(15, 20, 3, 8);
    ctx.fillRect(46, 20, 3, 8);
    // jagged fringe
    ctx.fillStyle = hairColor;
    for (let i = 0; i < 5; i++) {
      ctx.fillRect(18 + i * 6, 22, 4, 4);
    }
    ctx.fillStyle = shade(hairColor, 1.35);
    ctx.fillRect(23, 14, 4, 2);
    ctx.fillRect(35, 11, 3, 2);
  } else if (style === 'curly') {
    ctx.fillStyle = hairDark;
    const puffs = [
      [17, 23, 7], [23, 17, 7], [31, 14, 8], [40, 16, 7],
      [46, 22, 7], [48, 29, 6], [16, 31, 5]
    ];
    for (const [x, y, r] of puffs) circle(ctx, x, y, r, hairDark);
    ctx.fillStyle = hairColor;
    for (const [x, y, r] of puffs) circle(ctx, x - 1, y - 1, r - 2, hairColor);
    ctx.fillStyle = shade(hairColor, 1.3);
    circle(ctx, 24, 17, 3, shade(hairColor, 1.3));
    circle(ctx, 37, 15, 2, shade(hairColor, 1.3));
  } else if (style === 'long') {
    ctx.fillStyle = hairDark;
    ellipse(ctx, 32, 24, 17, 14, hairDark);
    ctx.fillStyle = hairColor;
    ellipse(ctx, 32, 23, 16, 12, hairColor);
    ctx.fillRect(14, 23, 5, 30);
    ctx.fillRect(45, 23, 5, 30);
    ctx.fillStyle = hairDark;
    ctx.fillRect(17, 22, 2, 12);
    ctx.fillRect(45, 22, 2, 12);
    ctx.fillStyle = shade(hairColor, 1.25);
    ctx.fillRect(22, 14, 5, 2);
    // fringe
    ctx.fillStyle = hairColor;
    for (let i = 0; i < 4; i++) ctx.fillRect(20 + i * 6, 23, 5, 3);
  } else {
    // short / old
    ctx.fillStyle = hairDark;
    ellipse(ctx, 32, 24, 16, 13, hairDark);
    ctx.fillStyle = hairColor;
    ellipse(ctx, 32, 23, 15, 11, hairColor);
    ctx.fillStyle = hairDark;
    ctx.fillRect(16, 24, 3, 10);
    ctx.fillRect(45, 24, 3, 10);
    if (char.old) {
      ctx.fillStyle = shade(hairColor, 0.82);
      ctx.fillRect(18, 23, 28, 3);
      ctx.fillStyle = skinDark;
      ctx.fillRect(24, 19, 16, 3);
    }
    ctx.fillStyle = shade(hairColor, 1.25);
    ctx.fillRect(22, 15, 6, 2);
    ctx.fillRect(33, 13, 5, 2);
  }

  // sideburns
  if (style !== 'long') {
    ctx.fillStyle = hairColor;
    ctx.fillRect(17, 27, 3, 7);
    ctx.fillRect(44, 27, 3, 7);
  }

  // ---- headband ----
  if (accessory === 'headband') {
    const band = char.headband || '#f4f4f4';
    ctx.fillStyle = shade(band, 0.72);
    ctx.fillRect(17, 26, 30, 4);
    ctx.fillStyle = band;
    ctx.fillRect(18, 26, 28, 3);
    // knot and tails
    ctx.fillStyle = shade(band, 0.85);
    ctx.fillRect(46, 25, 4, 5);
    ctx.fillStyle = band;
    ctx.fillRect(47, 24, 3, 3);
    ctx.fillStyle = shade(band, 0.8);
    ctx.fillRect(49, 27, 6, 2);
    ctx.fillRect(50, 30, 4, 2);
    ctx.fillStyle = shade(band, 1.2);
    ctx.fillRect(20, 26, 8, 1);
  }

  // ---- eyebrows ----
  ctx.fillStyle = char.old ? '#9a9a9a' : hairDark;
  ctx.fillRect(21, 30, 7, 2);
  ctx.fillRect(36, 30, 7, 2);
  if (char.old) {
    ctx.fillRect(21, 29, 3, 1);
    ctx.fillRect(40, 29, 3, 1);
  }

  // ---- eyes ----
  ctx.fillStyle = '#f7f3ea';
  ctx.fillRect(21, 33, 7, 4);
  ctx.fillRect(36, 33, 7, 4);
  const eyeColor = char.eyes || '#241a12';
  ctx.fillStyle = eyeColor;
  ctx.fillRect(24, 33, 3, 4);
  ctx.fillRect(39, 33, 3, 4);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(24, 33, 1, 1);
  ctx.fillRect(39, 33, 1, 1);
  // lower lid
  ctx.fillStyle = skinDark;
  ctx.fillRect(21, 37, 7, 1);
  ctx.fillRect(36, 37, 7, 1);

  // ---- nose ----
  ctx.fillStyle = skinDark;
  ctx.fillRect(31, 38, 2, 5);
  ctx.fillRect(29, 42, 2, 1);
  ctx.fillStyle = shade(skin, 1.1);
  ctx.fillRect(28, 38, 2, 3);

  // ---- mouth ----
  ctx.fillStyle = shade(skin, 0.55);
  ctx.fillRect(28, 46, 8, 1);
  ctx.fillRect(27, 45, 1, 1);
  ctx.fillRect(36, 45, 1, 1);
  ctx.fillStyle = shade(skin, 0.72);
  ctx.fillRect(30, 47, 4, 1);

  // ---- moustache / beard ----
  if (char.mustache) {
    ctx.fillStyle = char.old ? '#b8b8b8' : hairDark;
    ctx.fillRect(25, 43, 14, 2);
    ctx.fillRect(24, 44, 2, 1);
    ctx.fillRect(38, 44, 2, 1);
    ctx.fillStyle = '#7a5a44';
    ctx.fillRect(28, 45, 8, 1);
  }
  if (char.beard) {
    ctx.fillStyle = hairColor;
    ctx.fillRect(21, 44, 3, 4);
    ctx.fillRect(40, 44, 3, 4);
    ctx.fillRect(24, 48, 16, 2);
  }

  // ---- jersey sleeve shading ----
  ctx.fillStyle = 'rgba(0,0,0,.18)';
  ctx.fillRect(5, 66, 3, 6);
  ctx.fillRect(56, 66, 3, 6);
  ctx.fillStyle = 'rgba(255,255,255,.12)';
  ctx.fillRect(12, 60, 2, 8);
}

function drawNarrator(canvas) {
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, W, H);
  // stylised football
  const cx = 32, cy = 36, r = 20;
  circle(ctx, cx, cy, r + 1, '#0a1526');
  circle(ctx, cx, cy, r, '#e8eef8');
  ctx.fillStyle = '#1a2438';
  // pentagon-ish patches
  ctx.fillRect(28, 23, 8, 3);
  ctx.fillRect(24, 29, 4, 4);
  ctx.fillRect(36, 29, 4, 4);
  ctx.fillRect(29, 35, 6, 5);
  ctx.fillRect(23, 42, 5, 4);
  ctx.fillRect(36, 42, 5, 4);
  ctx.fillRect(28, 49, 8, 3);
  ctx.fillStyle = 'rgba(255,255,255,.7)';
  ctx.fillRect(23, 24, 3, 2);
  ctx.fillStyle = 'rgba(0,0,0,.25)';
  ctx.fillRect(18, 50, 28, 3);
  // little shine
  ctx.fillStyle = 'rgba(255,255,255,.35)';
  ctx.fillRect(20, 28, 2, 6);
}

export function drawTrophy(canvas) {
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, W, H);
  const gold = '#ffd23f';
  const goldDark = '#b57600';
  ctx.fillStyle = goldDark;
  ctx.fillRect(18, 8, 28, 4);
  ctx.fillStyle = gold;
  ctx.fillRect(20, 12, 24, 4);
  ctx.fillRect(22, 16, 20, 10);
  ctx.fillRect(25, 26, 14, 6);
  ctx.fillStyle = goldDark;
  ctx.fillRect(22, 16, 3, 10);
  ctx.fillRect(39, 16, 3, 10);
  ctx.fillStyle = gold;
  ctx.fillRect(24, 32, 16, 4);
  ctx.fillRect(30, 36, 4, 12);
  ctx.fillRect(22, 48, 20, 5);
  ctx.fillStyle = goldDark;
  ctx.fillRect(22, 52, 20, 3);
  ctx.fillStyle = '#fff6c4';
  ctx.fillRect(28, 18, 2, 8);
  ctx.fillRect(25, 10, 3, 2);
  // handles
  ctx.strokeStyle = goldDark;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(18, 20, 7, -1.2, 1.4); ctx.stroke();
  ctx.beginPath(); ctx.arc(46, 20, 7, 1.7, 4.4); ctx.stroke();
}

// ---------------------------------------------------------------------------
// Canvas pitch renderer — vertical pitch, chunky pixel players.
// ---------------------------------------------------------------------------

const CW = 600, CH = 760;
const PX = 55, PY = 70, PW = 490, PH = 620;

function toPx(x, y) {
  return { x: PX + (x / 100) * PW, y: PY + (y / 100) * PH };
}

function rngFactory(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function drawStatic(ctx) {
  // night sky / stands
  ctx.fillStyle = '#060b16';
  ctx.fillRect(0, 0, CW, CH);
  ctx.fillStyle = '#0a1322';
  ctx.fillRect(0, 0, CW, 54);
  ctx.fillRect(0, 706, CW, CH - 706);
  ctx.fillRect(0, 54, PX - 18, 652);
  ctx.fillRect(PX + PW + 18, 54, CW - (PX + PW + 18), 652);

  // crowd dots
  const rnd = rngFactory(77);
  const crowdColors = ['#2a3f63', '#39547f', '#4d6b99', '#6d4a5e', '#7a5c3a', '#3f5f6d'];
  for (let i = 0; i < 900; i++) {
    const side = i % 4;
    let x, y;
    if (side === 0) { x = rnd() * CW; y = 4 + rnd() * 44; }
    else if (side === 1) { x = rnd() * CW; y = 710 + rnd() * 44; }
    else if (side === 2) { x = 4 + rnd() * (PX - 26); y = 58 + rnd() * 640; }
    else { x = PX + PW + 26 + rnd() * (CW - PX - PW - 30); y = 58 + rnd() * 640; }
    ctx.fillStyle = crowdColors[Math.floor(rnd() * crowdColors.length)];
    const s = rnd() < 0.25 ? 3 : 2;
    ctx.fillRect(x | 0, y | 0, s, s);
  }

  // advertising boards
  const ads = ['#173a6b', '#6b1f2a', '#1c5a3a', '#5b3a12', '#2c2c54'];
  for (let i = 0; i < 14; i++) {
    ctx.fillStyle = ads[i % ads.length];
    ctx.fillRect(6, 70 + i * 44, 26, 34);
    ctx.fillRect(CW - 32, 70 + i * 44, 26, 34);
    ctx.fillStyle = 'rgba(255,255,255,.18)';
    ctx.fillRect(9, 76 + i * 44, 20, 3);
    ctx.fillRect(CW - 29, 76 + i * 44, 20, 3);
  }

  // grass
  for (let i = 0; i < 10; i++) {
    ctx.fillStyle = i % 2 === 0 ? '#1a6339' : '#175a34';
    ctx.fillRect(PX, PY + i * (PH / 10), PW, PH / 10 + 1);
  }
  // mowing shimmer
  ctx.fillStyle = 'rgba(255,255,255,.025)';
  for (let i = 0; i < 10; i += 2) ctx.fillRect(PX, PY + i * (PH / 10), PW, 2);

  const line = 'rgba(232,244,232,.82)';
  ctx.strokeStyle = line;
  ctx.fillStyle = line;
  ctx.lineWidth = 2;

  // boundary
  ctx.strokeRect(PX + 1, PY + 1, PW - 2, PH - 2);
  // halfway
  ctx.beginPath(); ctx.moveTo(PX, PY + PH / 2); ctx.lineTo(PX + PW, PY + PH / 2); ctx.stroke();
  // centre circle
  ctx.beginPath(); ctx.arc(PX + PW / 2, PY + PH / 2, 62, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(PX + PW / 2, PY + PH / 2, 3, 0, Math.PI * 2); ctx.fill();

  // penalty boxes + goal areas
  const boxW = PW * 0.6, boxD = 108;
  const smallW = PW * 0.3, smallD = 46;
  ctx.strokeRect(PX + (PW - boxW) / 2, PY, boxW, boxD);
  ctx.strokeRect(PX + (PW - boxW) / 2, PY + PH - boxD, boxW, boxD);
  ctx.strokeRect(PX + (PW - smallW) / 2, PY, smallW, smallD);
  ctx.strokeRect(PX + (PW - smallW) / 2, PY + PH - smallD, smallW, smallD);

  // penalty spots + arcs
  ctx.beginPath(); ctx.arc(PX + PW / 2, PY + 74, 2.5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(PX + PW / 2, PY + PH - 74, 2.5, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.arc(PX + PW / 2, PY + 74, 44, 0.35, Math.PI - 0.35);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(PX + PW / 2, PY + PH - 74, 44, Math.PI + 0.35, Math.PI * 2 - 0.35);
  ctx.stroke();

  // corner arcs
  const corners = [
    [PX, PY, 0, Math.PI / 2],
    [PX + PW, PY, Math.PI / 2, Math.PI],
    [PX, PY + PH, -Math.PI / 2, 0],
    [PX + PW, PY + PH, Math.PI, Math.PI * 1.5]
  ];
  for (const [cx, cy, a0, a1] of corners) {
    ctx.beginPath(); ctx.arc(cx, cy, 11, a0, a1); ctx.stroke();
  }

  // goals + nets
  const gw = 88;
  const gx = PX + PW / 2 - gw / 2;
  ctx.fillStyle = 'rgba(225,240,255,.08)';
  ctx.fillRect(gx, PY - 20, gw, 20);
  ctx.fillRect(gx, PY + PH, gw, 20);
  ctx.strokeStyle = 'rgba(225,240,255,.45)';
  ctx.lineWidth = 1;
  for (let i = 0; i <= gw; i += 8) {
    ctx.beginPath(); ctx.moveTo(gx + i, PY - 20); ctx.lineTo(gx + i, PY); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(gx + i, PY + PH); ctx.lineTo(gx + i, PY + PH + 20); ctx.stroke();
  }
  for (let j = 0; j <= 20; j += 6) {
    ctx.beginPath(); ctx.moveTo(gx, PY - 20 + j); ctx.lineTo(gx + gw, PY - 20 + j); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(gx, PY + PH + j); ctx.lineTo(gx + gw, PY + PH + j); ctx.stroke();
  }
  ctx.strokeStyle = '#f4fbff';
  ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(gx, PY); ctx.lineTo(gx + gw, PY); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(gx, PY + PH); ctx.lineTo(gx + gw, PY + PH); ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(gx, PY - 20); ctx.lineTo(gx, PY); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(gx + gw, PY - 20); ctx.lineTo(gx + gw, PY); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(gx, PY + PH); ctx.lineTo(gx, PY + PH + 20); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(gx + gw, PY + PH); ctx.lineTo(gx + gw, PY + PH + 20); ctx.stroke();

  // subtle vignette
  const grad = ctx.createRadialGradient(CW / 2, CH / 2, 240, CW / 2, CH / 2, 520);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,.34)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, CW, CH);
}

function drawPlayer(ctx, px, py, p, team, isCarrier, bob) {
  const skin = p.look?.skin || '#a96b45';
  const hair = p.look?.hairColor || '#1a1410';
  const style = p.look?.hair || 'short';
  const shirt = p.role === 'GK' ? (team.colors.gk || '#ff8c42') : team.colors.shirt;
  const shorts = team.colors.shorts;
  const trim = team.colors.trim;
  const s = 1.45;
  const y = py + bob;

  // shadow
  ctx.fillStyle = 'rgba(0,0,0,.3)';
  ctx.beginPath();
  ctx.ellipse(px, y + 1, 8, 3, 0, 0, Math.PI * 2);
  ctx.fill();

  // legs
  ctx.fillStyle = skin;
  ctx.fillRect(px - 4, y - 7, 3, 6);
  ctx.fillRect(px + 1, y - 7, 3, 6);
  // boots
  ctx.fillStyle = '#121212';
  ctx.fillRect(px - 5, y - 2, 4, 2);
  ctx.fillRect(px + 1, y - 2, 4, 2);
  // shorts
  ctx.fillStyle = shorts;
  ctx.fillRect(px - 5, y - 11, 10, 4);
  ctx.fillStyle = trim;
  ctx.fillRect(px - 5, y - 11, 10, 1);
  // shirt
  ctx.fillStyle = shirt;
  ctx.fillRect(px - 5, y - 19, 10, 8);
  ctx.fillStyle = trim;
  ctx.fillRect(px - 5, y - 19, 10, 2);
  ctx.fillRect(px - 5, y - 13, 10, 1);
  // sleeves
  ctx.fillStyle = shirt;
  ctx.fillRect(px - 7, y - 18, 2, 6);
  ctx.fillRect(px + 5, y - 18, 2, 6);
  ctx.fillStyle = skin;
  ctx.fillRect(px - 7, y - 13, 2, 3);
  ctx.fillRect(px + 5, y - 13, 2, 3);
  // number
  ctx.fillStyle = team.colors.text || '#111';
  ctx.fillRect(px - 1, y - 17, 2, 3);
  // neck
  ctx.fillStyle = skin;
  ctx.fillRect(px - 2, y - 21, 4, 2);
  // head
  ctx.fillStyle = skin;
  ctx.fillRect(px - 3, y - 26, 6, 5);
  // hair
  ctx.fillStyle = hair;
  if (style === 'spiky') {
    ctx.fillRect(px - 4, y - 28, 8, 3);
    ctx.fillRect(px - 4, y - 30, 2, 2);
    ctx.fillRect(px, y - 31, 2, 3);
    ctx.fillRect(px + 3, y - 30, 2, 2);
  } else if (style === 'curly') {
    ctx.fillRect(px - 5, y - 29, 10, 4);
    ctx.fillRect(px - 5, y - 31, 2, 2);
    ctx.fillRect(px + 3, y - 31, 2, 2);
  } else if (style === 'long') {
    ctx.fillRect(px - 4, y - 28, 8, 3);
    ctx.fillRect(px - 5, y - 26, 2, 4);
    ctx.fillRect(px + 3, y - 26, 2, 4);
  } else {
    ctx.fillRect(px - 4, y - 28, 8, 3);
  }
  // eyes
  ctx.fillStyle = '#1a1410';
  ctx.fillRect(px - 2, y - 24, 1, 1);
  ctx.fillRect(px + 1, y - 24, 1, 1);

  if (isCarrier) {
    const t = (Date.now() % 900) / 900;
    const ay = y - 38 - Math.sin(t * Math.PI * 2) * 2;
    ctx.fillStyle = '#ffd23f';
    ctx.beginPath();
    ctx.moveTo(px, ay + 7);
    ctx.lineTo(px - 5, ay);
    ctx.lineTo(px + 5, ay);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(255,210,63,.28)';
    ctx.beginPath();
    ctx.ellipse(px, y + 1, 11, 4, 0, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawBall(ctx, x, y, scale = 1) {
  ctx.fillStyle = 'rgba(0,0,0,.32)';
  ctx.beginPath();
  ctx.ellipse(x + 1, y + 2, 5 * scale, 2.4 * scale, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#f7f7f2';
  ctx.beginPath();
  ctx.arc(x, y, 5 * scale, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#18202e';
  ctx.fillRect(x - 1.5, y - 2, 3, 2);
  ctx.fillRect(x - 4, y + 1, 2, 2);
  ctx.fillRect(x + 2, y + 1, 2, 2);
}

export class PitchRenderer {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.ctx.imageSmoothingEnabled = false;
    this.bg = document.createElement('canvas');
    this.bg.width = CW;
    this.bg.height = CH;
    drawStatic(this.bg.getContext('2d'));
    this.state = null;
    this.visual = new Map();
    this.ball = { x: 300, y: 380 };
    this.trail = [];
    this.running = false;
    this.raf = 0;
    this.last = 0;
    this.shakeUntil = 0;
    this.flash = 0;
  }

  setMatch(state) {
    this.state = state;
    this.visual.clear();
    for (const team of state.teams) {
      for (const p of team.players) {
        const pt = toPx(p.x, p.y);
        this.visual.set(p.id, { x: pt.x, y: pt.y });
      }
    }
    const b = toPx(state.ball.x, state.ball.y);
    this.ball = { x: b.x, y: b.y };
    this.trail = [];
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.last = performance.now();
    const loop = (t) => {
      if (!this.running) return;
      const dt = Math.min(40, t - this.last);
      this.last = t;
      this.step(dt);
      this.draw(t);
      this.raf = requestAnimationFrame(loop);
    };
    this.raf = requestAnimationFrame(loop);
  }

  stop() {
    this.running = false;
    cancelAnimationFrame(this.raf);
  }

  shake(ms = 400) {
    this.shakeUntil = performance.now() + ms;
  }

  step(dt) {
    if (!this.state) return;
    const k = 1 - Math.pow(0.82, dt / 16);
    for (const team of this.state.teams) {
      for (const p of team.players) {
        const target = toPx(p.x, p.y);
        const v = this.visual.get(p.id) || target;
        v.x += (target.x - v.x) * k;
        v.y += (target.y - v.y) * k;
        this.visual.set(p.id, v);
      }
    }
    const b = toPx(this.state.ball.x, this.state.ball.y);
    this.ball.x += (b.x - this.ball.x) * Math.min(0.5, k * 1.7);
    this.ball.y += (b.y - this.ball.y) * Math.min(0.5, k * 1.7);

    if (this.trail.length === 0 || Math.hypot(this.trail[0].x - this.ball.x, this.trail[0].y - this.ball.y) > 6) {
      this.trail.unshift({ x: this.ball.x, y: this.ball.y, life: 1 });
      if (this.trail.length > 8) this.trail.pop();
    }
    for (const t of this.trail) t.life -= dt / 420;
    this.trail = this.trail.filter(t => t.life > 0);
  }

  draw(t) {
    const ctx = this.ctx;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, CW, CH);
    let ox = 0, oy = 0;
    if (t < this.shakeUntil) {
      ox = (Math.random() - 0.5) * 8;
      oy = (Math.random() - 0.5) * 8;
    }
    ctx.save();
    ctx.translate(ox, oy);
    ctx.drawImage(this.bg, 0, 0);

    if (!this.state) {
      ctx.restore();
      return;
    }

    // camera flashes in the crowd
    if (Math.random() < 0.08) {
      ctx.fillStyle = 'rgba(255,255,255,.8)';
      const side = Math.random() < 0.5;
      const x = side ? 4 + Math.random() * (PX - 20) : PX + PW + 24 + Math.random() * (CW - PX - PW - 30);
      ctx.fillRect(x, 60 + Math.random() * 620, 2, 2);
    }

    const carrier = this.state.carrier;
    for (const team of this.state.teams) {
      for (const p of team.players) {
        const v = this.visual.get(p.id);
        if (!v) continue;
        const bob = p.id === carrier ? 0 : Math.sin(t / 260 + p.slot) * 1.2;
        drawPlayer(ctx, v.x, v.y, p, team, p.id === carrier, bob);
      }
    }

    // ball trail
    for (const tr of this.trail) {
      ctx.fillStyle = `rgba(255,255,255,${tr.life * 0.25})`;
      ctx.beginPath();
      ctx.arc(tr.x, tr.y, 2 + tr.life * 2, 0, Math.PI * 2);
      ctx.fill();
    }
    drawBall(ctx, this.ball.x, this.ball.y, 1.15);

    // subtle scanline shimmer over the pitch
    ctx.fillStyle = 'rgba(255,255,255,.018)';
    for (let y = PY; y < PY + PH; y += 4) ctx.fillRect(PX, y, PW, 1);

    ctx.restore();
  }
}

export { CW, CH, toPx };

content.text:
Now audio.js.

Implement robust WebAudio. Need to avoid errors when AudioContext unavailable. Use try/catch.

```js
export class GameAudio {
 constructor(){ this.ctx=null; this.muted=localStorage...; this.musicTimer=null; this.musicNodes=[]; this.crowd=null; this.track=null; }
 init(){ if(!this.ctx){ const AC=window.AudioContext||window.webkitAudioContext; ... } if(this.ctx.state==='suspended') this.ctx.resume(); }
 ...
}
```

Music patterns. Let's compose simple:
- title: 8 steps per bar, 4 bars, tempo 100, major.
- story: gentle.
- match: samba 132 BPM, 16 steps/bar, 4 bars.
- final: minor dramatic.

We can implement one generic sequencer:
```js
startMusic(name) {
  this.stopMusic();
  const pat = PATTERNS[name];
  this.current = pat; this.step=0; this.nextTime=ctx.currentTime+0.05;
  this.musicGain.gain.value = pat.gain;
  this.musicTimer=setInterval(()=>this.schedule(),60);
}
schedule(){
 while(this.nextTime < this.ctx.currentTime+0.25){
   this.playStep(this.current, this.step, this.nextTime);
   this.nextTime += this.current.stepDur;
   this.step=(this.step+1)%this.current.lead.length;
 }
}
```
Play lead with square/triangle, bass, hat. Note arrays with MIDI or null; 0 rest. Use note names converted.

Patterns:
- match (A minor samba): stepDur = 60/132/4 = 0.1136.
  lead 32 steps: [69,null,72,69,76,null,72,69, 67,null,71,67,74,null,71,67, 69,null,72,69,76,79,76,72, 67,71,74,79,null,76,72,67] etc.
  bass every 4 steps: [45,null,null,null,45,...] with syncopation.
  hat noise on every step low volume, accent.
- title: stepDur 60/96/4=0.156; major C: lead [72,76,79,76, 74,77,81,77, ...].
- story: sparse.
- final: minor with faster.

Maybe simpler: use one "match" theme and one "title" theme and vary pitch. That's fine.

SFX:
- blip: square 880→1100 0.05s.
- select: 660 0.04.
- confirm: two notes.
- kick: noise burst + sine drop.
- whistle: square high with vibrato 0.25.
- goal: arpeggio C E G C + crowd cheer.
- save: thud + crowd "ooh" (noise low).
- tackle: noise.
- special: rising sweep.
- win/lose jingle.

Crowd: start/stop:
```js
startCrowd(){ if(!ctx) return; create bufferSource noise loop -> bandpass 500 -> gain 0.035 -> destination }
```
Buffer 2s white noise. Also `cheer(intensity)` creates noise burst through bandpass with gain envelope 0.12 over 1.2s.

Volume master 0.6. Muted sets master gain 0.

localStorage mute.

Need `document` reference; fine.

Write.

input.content:
// ---------------------------------------------------------------------------
// Tiny chiptune + SFX engine (WebAudio, no assets).
// ---------------------------------------------------------------------------

const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);

const PATTERNS = {
  title: {
    bpm: 104, gain: 0.16,
    lead: [
      72, null, 76, null, 79, null, 76, null,
      74, null, 77, null, 81, null, 77, null,
      72, null, 76, null, 79, 81, 79, 76,
      74, 72, 69, null, 67, null, 72, null
    ],
    bass: [48, null, null, null, 48, null, 43, null, 48, null, null, null, 43, null, 45, null],
    hat: 1
  },
  story: {
    bpm: 76, gain: 0.12,
    lead: [
      64, null, null, null, 67, null, 71, null,
      69, null, null, null, 64, null, 62, null,
      60, null, null, null, 64, null, 67, null,
      62, null, 59, null, 64, null, null, null
    ],
    bass: [40, null, null, null, 40, null, null, null, 45, null, null, null, 43, null, null, null],
    hat: 0
  },
  match: {
    bpm: 136, gain: 0.16,
    lead: [
      69, null, 72, 69, 76, null, 72, 69,
      67, null, 71, 67, 74, null, 71, 67,
      69, 72, 76, 79, 76, 72, 69, 72,
      67, 71, 74, 79, null, 76, 72, 67
    ],
    bass: [
      45, null, 45, null, 52, null, 45, null,
      43, null, 43, null, 50, null, 43, null,
      45, null, 45, null, 52, null, 57, null,
      43, null, 50, null, 43, null, 45, null
    ],
    hat: 1
  },
  final: {
    bpm: 148, gain: 0.17,
    lead: [
      62, null, 65, 69, 74, 69, 65, 62,
      60, null, 64, 67, 72, 67, 64, 60,
      58, null, 62, 65, 70, 65, 62, 58,
      60, 64, 67, 72, 76, 72, 67, 64
    ],
    bass: [
      38, null, 38, 38, 45, null, 38, null,
      36, null, 36, 36, 43, null, 36, null,
      34, null, 34, 34, 41, null, 34, null,
      36, null, 43, null, 36, null, 38, null
    ],
    hat: 1
  }
};

export class GameAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.crowdGain = null;
    this.crowdSource = null;
    this.timer = null;
    this.pattern = null;
    this.step = 0;
    this.nextTime = 0;
    this.muted = false;
    try { this.muted = localStorage.getItem('cs_ss_muted') === '1'; } catch {}
    this.started = false;
  }

  init() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return false;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.55;
      this.master.connect(this.ctx.destination);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = 0;
      this.musicGain.connect(this.master);
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = 0.9;
      this.sfxGain.connect(this.master);
      this.crowdGain = this.ctx.createGain();
      this.crowdGain.gain.value = 0;
      this.crowdGain.connect(this.master);
      this.makeNoise();
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
    this.started = true;
    return true;
  }

  makeNoise() {
    const len = this.ctx.sampleRate * 2;
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    this.noiseBuffer = buffer;
  }

  setMuted(m) {
    this.muted = m;
    try { localStorage.setItem('cs_ss_muted', m ? '1' : '0'); } catch {}
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.02);
    }
  }

  toggleMute() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  tone(freq, dur, type = 'square', vol = 0.2, when = null, slide = null) {
    if (!this.ctx) return;
    const t = when ?? this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t + dur);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.008);
    g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
    osc.connect(g).connect(this.sfxGain);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise(dur, vol = 0.2, when = null, filterFreq = 1200, type = 'bandpass') {
    if (!this.ctx) return;
    const t = when ?? this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = filterFreq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
    src.connect(f).connect(g).connect(this.sfxGain);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  sfx(name) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    switch (name) {
      case 'blip': this.tone(880, 0.045, 'square', 0.05); break;
      case 'select': this.tone(660, 0.05, 'square', 0.07); this.tone(990, 0.04, 'square', 0.05, t + 0.05); break;
      case 'confirm': this.tone(660, 0.07, 'square', 0.09); this.tone(880, 0.09, 'square', 0.09, t + 0.07); this.tone(1320, 0.12, 'square', 0.07, t + 0.15); break;
      case 'back': this.tone(440, 0.07, 'square', 0.06); this.tone(330, 0.08, 'square', 0.06, t + 0.06); break;
      case 'kick':
        this.noise(0.09, 0.28, t, 900, 'lowpass');
        this.tone(150, 0.09, 'sine', 0.28, t, 60);
        break;
      case 'pass': this.noise(0.05, 0.12, t, 1800); break;
      case 'tackle': this.noise(0.16, 0.3, t, 500, 'lowpass'); this.tone(90, 0.12, 'sawtooth', 0.12, t, 45); break;
      case 'save': this.noise(0.12, 0.24, t, 700); this.tone(220, 0.1, 'square', 0.08, t, 120); break;
      case 'whistle':
        this.tone(2200, 0.14, 'square', 0.1, t, 2400);
        this.tone(2200, 0.22, 'square', 0.1, t + 0.18, 2000);
        break;
      case 'goal':
        this.noise(0.7, 0.3, t, 600, 'lowpass');
        [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.18, 'square', 0.12, t + i * 0.08));
        this.tone(1319, 0.5, 'square', 0.09, t + 0.36);
        this.cheer(0.5);
        break;
      case 'special':
        [330, 440, 554, 659, 880, 1109].forEach((f, i) => this.tone(f, 0.09, 'square', 0.08, t + i * 0.05));
        this.noise(0.4, 0.15, t, 1600);
        break;
      case 'win':
        [523, 659, 784, 1047, 1319].forEach((f, i) => this.tone(f, 0.24, 'square', 0.1, t + i * 0.13));
        break;
      case 'lose':
        [392, 349, 311, 262].forEach((f, i) => this.tone(f, 0.28, 'triangle', 0.1, t + i * 0.17));
        break;
      case 'tick': this.tone(1200, 0.03, 'square', 0.04); break;
      default: break;
    }
  }

  cheer(intensity = 0.4) {
    if (!this.ctx || this.muted) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = 900;
    f.Q.value = 0.6;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(intensity, t + 0.08);
    g.gain.exponentialRampToValueAtTime(0.001, t + 1.4);
    src.connect(f).connect(g).connect(this.sfxGain);
    src.start(t);
    src.stop(t + 1.5);
  }

  startMusic(name) {
    if (!this.ctx) return;
    const pat = PATTERNS[name];
    if (!pat) return;
    this.stopMusic();
    this.pattern = pat;
    this.step = 0;
    this.nextTime = this.ctx.currentTime + 0.08;
    this.musicGain.gain.setTargetAtTime(pat.gain, this.ctx.currentTime, 0.2);
    this.timer = setInterval(() => this.schedule(), 60);
    this.schedule();
  }

  schedule() {
    if (!this.ctx || !this.pattern) return;
    const pat = this.pattern;
    const stepDur = 60 / pat.bpm / 4;
    while (this.nextTime < this.ctx.currentTime + 0.25) {
      const i = this.step % pat.lead.length;
      const lead = pat.lead[i];
      const bass = pat.bass[i % pat.bass.length];
      const t = this.nextTime;
      if (lead) this.musicTone(midi(lead), stepDur * 1.5, 'square', 0.16, t);
      if (bass) this.musicTone(midi(bass), stepDur * 2.4, 'triangle', 0.2, t);
      if (pat.hat && i % 2 === 0) this.musicNoise(0.035, 0.035, t, 6000, 'highpass');
      if (pat.hat && i % 8 === 4) this.musicNoise(0.08, 0.05, t, 3000);
      this.nextTime += stepDur;
      this.step++;
    }
  }

  musicTone(freq, dur, type, vol, t) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    osc.connect(g).connect(this.musicGain);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  musicNoise(dur, vol, t, freq, type = 'bandpass') {
    if (!this.ctx) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    src.connect(f).connect(g).connect(this.musicGain);
    src.start(t);
    src.stop(t + dur + 0.02);
  }

  stopMusic() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
    this.pattern = null;
    if (this.musicGain && this.ctx) {
      this.musicGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.05);
    }
  }

  startCrowd() {
    if (!this.ctx) return;
    if (this.crowdSource) return;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const f = this.ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = 520;
    f.Q.value = 0.4;
    src.connect(f).connect(this.crowdGain);
    src.start();
    this.crowdSource = src;
    this.crowdGain.gain.setTargetAtTime(0.05, this.ctx.currentTime, 0.5);
  }

  stopCrowd() {
    if (this.crowdGain && this.ctx) this.crowdGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.2);
    if (this.crowdSource) {
      try { this.crowdSource.stop(this.ctx.currentTime + 0.6); } catch {}
      this.crowdSource = null;
    }
  }
}

export const audio = new GameAudio();

content.text:
Now main.js — the big one. Need careful implementation.

Let's outline:

```js
import { CHAPTERS, CHARACTERS, ENDING, STAT_LABELS } from './story.js';
import * as engine from './engine.js';
import { PitchRenderer } from './render.js';
import { drawPortrait, drawTrophy } from './portrait.js';
import { audio } from './audio.js';

const $ = (id) => document.getElementById(id);
const SAVE_KEY = ...
const screens = {title, map, story, training, match, result}
let save = loadSave() || null;
let currentChapter = null;
let matchState = null;
let renderer = null;
let abortMatch = false;
let paused = false;
let activeChoice = null;
let resultContinue = null;

const wait = ms => new Promise(r=>setTimeout(r,ms));
```

Save:
```js
function defaultSave() {
 return {version:1, chapter:0, stats:{shot:10,dribble:10,pass:8,tackle:5,speed:9,stamina:100}, moves:[], cleared:[], trophies:0, completed:false, matches:0};
}
function loadSave(){ try{ const raw=localStorage.getItem(SAVE_KEY); if(!raw) return null; const s=JSON.parse(raw); if(!s.stats) return null; return {...defaultSave(), ...s, stats:{...defaultSave().stats,...s.stats}} }catch{return null} }
function persist(){ try{ localStorage.setItem(SAVE_KEY, JSON.stringify(save)) }catch{} }
```
When New Story: save = defaultSave(); persist; go map. If existing, ask confirm.

Title buttons:
- new: if existing && (save.chapter>0||cleared.length) askConfirm. Then reset.
- continue: if save exists → map else new.
- how → overlay.
- sound? no button on title; map has.

Portrait drawing on title/map. `drawPortrait($('title-portrait'), CHARACTERS.carlos)` and map.

`document.fonts.ready.then(...)` maybe redraw canvas text? Portraits don't use fonts. Fine.

Show screen:
```js
function showScreen(name){ Object.entries(screens).forEach(([k,el])=>el.classList.toggle('hidden',k!==name)); currentScreen=name; }
```

Map render:
```js
function renderMap(){
 showScreen('map');
 drawPortrait(mapPortrait, {...CHARACTERS.carlos, jersey:..., number:10});
 // stats bars
 statList.innerHTML = Object.entries(...).map...
 // chapters
 chapterList.innerHTML = CHAPTERS.map((ch,i)=>{ const done=save.cleared.includes(ch.id); const current=i===save.chapter; const locked=i>save.chapter; ... }).join('');
 // click handlers
}
```
If save.chapter >= CHAPTERS.length (completed), all done; current none. Clicking any cleared chapter allows replay. Hint "Story complete. Replay any chapter."
Chapter card state: 'CLEARED' / 'NEXT' / 'LOCKED'. Current = i===save.chapter.
Click: if locked toast; else startChapter(i).

Stat bars: value/20*100 for skills; stamina/140.

`startChapter(index)`:
```js
currentChapter = CHAPTERS[index];
const firstTime = !save.cleared.includes(ch.id) && index===save.chapter;
if (firstTime) { await playStory(ch.intro, ch, {card:true}); await showTraining(ch); }
else { await playStory(ch.preMatch, ch, {card:true, short:true}); } // maybe intro? Replay skip.
await playStory(ch.preMatch, ch, {card:false});
await beginMatch(ch);
```
Careful: for firstTime, training then preMatch. For replay, show preMatch only (and maybe a short "rematch" card).

Maybe show intro for replay too? Could be long; skip. Fine.

Training: if stat at cap, still.

Story player implementation:

```js
let storyAdvance = null;
function playStory(lines, chapter, opts={}) {
  return new Promise(resolve => {
    showScreen('story');
    const sky=$('story-sky'); sky.style.background = chapter.sky;
    // chapter card
    const card=$('chapter-card');
    if (opts.card) { set texts; card.classList.remove('hidden'); card animation; }
    ...
    let index=0, typing=false, full='', charIndex=0, timer=null;
    const finish = () => { cleanup; resolve(); }
    function renderLine() { ... typewriter }
    function advance() { if typing → complete; else index++ → render or finish }
    ...
  });
}
```

Need the chapter card to show for ~1.8s then auto-hide, but user can tap to skip? On tap, hide card and show first line. Implement: if card visible, tap hides card. Set timeout 2000 to hide. But the line can render behind; fine.

Typewriter:
```js
function typeLine(text, speaker, portraitChar) {
  clearInterval(timer); full=text; el.textContent=''; charIndex=0; typing=true;
  timer=setInterval(()=>{ charIndex++; el.textContent=text.slice(0,charIndex); if(charIndex%3===0) audio.sfx('blip'); if(charIndex>=text.length){clear; typing=false;} }, 16);
}
```
If reduced motion (prefers-reduced-motion), show instantly. Add check.

Portrait: for narrator, drawNarrator via drawPortrait(canvas,{narrator:true}); frame.classList.add('narrator'); speaker 'NARRATION'; else drawPortrait with char, frame normal, speaker char.short/name.

Speaker plate color maybe per character? Keep yellow.

Event listeners: story screen pointerdown; keydown global. Need remove on finish. Use `onKey` and `onPointer`.
Careful: pointerdown on skip button also triggers screen advance; stopPropagation in skip handler.

Skip: finish all lines → resolve immediately. But if called from card, fine.

`playStory` resolve after last line advance. Add next-cue blinking hidden while typing? Show when line complete.

The story screen needs `dialogue-box` hidden while chapter card? Could keep. Simpler: card overlays, dialogue behind.

Training screen: render cards, promise. On click apply:
```js
save.stats[stat] = clamp(...); persist(); audio confirm; toast; resolve();
```
Then show preMatch story.

`beginMatch(chapter)`:
```js
showScreen('match');
const home = chapter.match.home(save), away = chapter.match.away();
matchState = engine.createMatch({home,away,playerTeam:0,minutes:...,goldenGoal:...,difficulty:...});
setupHUD();
renderer = new PitchRenderer(canvas); renderer.setMatch(state); renderer.start();
audio.init(); audio.startMusic(chapter.id==='ch4'?'final':'match'); audio.startCrowd();
audio.sfx('whistle');
await runMatch();
```
Maybe `beginMatch` returns result; handle in `finishMatch`.

`setupHUD` sets names, swatch colors, etc.

`updateHUD`:
- score, clock, half label: '1ST HALF', '2ND HALF', 'EXTRA TIME', 'SUDDEN DEATH'? `state.extra ? 'EXTRA TIME' : state.half===1?'1ST HALF':'2ND HALF'`.
- stamina fill width, low class.
- possession label: `YOUR ATTACK` / `${away.short} ATTACK` / 'KICK OFF' if minute 0? Use state.possession.
- log: last event text or state.log last.

`runMatch` as above.

Command menus:
```js
function renderAttackMenu(resolve) {
  const panel = $('commands');
  panel.className = 'command-panel';
  panel.innerHTML = '';
  const add = (label, sub, cls, action, disabled) => { button... onclick = () => { audio.sfx('select'); resolve(action); } }
  add('DRIBBLE','BEAT YOUR MAN','', {type:'dribble'});
