const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const URL = 'http://localhost:3002';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

async function stopMeter(page) {
  await page.waitForSelector('#meter-layer:not(.hidden)', { timeout: 4000 });
  const deadline = Date.now() + 6000;
  while (Date.now() < deadline) {
    const hidden = await page.evaluate(() => document.getElementById('meter-layer').classList.contains('hidden'));
    if (hidden) return;
    const left = await page.evaluate(() => parseFloat(document.getElementById('meter-marker').style.left || '0'));
    if (Math.abs(left - 50) < 7) {
      await page.keyboard.press('Space');
      await sleep(850);
      return;
    }
    await sleep(18);
  }
  await page.keyboard.press('Space');
  await sleep(850);
}

async function clickIfVisible(page, selector, timeout = 1200) {
  try {
    const el = page.locator(selector).first();
    if (await el.isVisible({ timeout })) { await el.click(); return true; }
  } catch {}
  return false;
}

async function skipStory(page) {
  if (await page.locator('#screen-story:not(.hidden)').isVisible().catch(() => false)) {
    await clickIfVisible(page, '#story-skip');
    await sleep(200);
  }
}

async function playChapter(page, chapterIndex, label) {
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.getByRole('button', { name: 'NEW STORY' }).click();
  await page.locator('.chapter').nth(chapterIndex).click();
  await sleep(300);
  await skipStory(page);
  await sleep(300);
  // training
  if (await page.locator('.training-card').first().isVisible().catch(() => false)) {
    await page.locator('.training-card').nth(1).click();
    await sleep(800);
    await skipStory(page);
  }
  await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 8000 });
  await sleep(600);

  let turns = 0;
  for (let i = 0; i < 240; i++) {
    if (await page.locator('#screen-result:not(.hidden)').isVisible().catch(() => false)) break;
    if (await page.locator('#screen-match.hidden').isVisible().catch(() => false)) break;

    // halftime / extra-time modal
    const modal = page.locator('#screen-match .overlay .modal');
    if (await modal.isVisible().catch(() => false)) {
      const btn = modal.locator('button').last();
      if (await btn.isVisible().catch(() => false)) { await btn.click(); await sleep(500); continue; }
    }

    // meter
    if (await page.locator('#meter-layer:not(.hidden)').isVisible().catch(() => false)) {
      await stopMeter(page);
      continue;
    }

    const cmds = page.locator('#commands .cmd:not([disabled])');
    const count = await cmds.count();
    if (!count) { await sleep(150); continue; }

    const possession = await page.locator('#possession-label').textContent().catch(() => '');
    const yours = possession.includes('YOUR');

    if (yours) {
      const labels = await cmds.allTextContents();
      const idx = (txt) => labels.findIndex(t => t.includes(txt));
      // pass to Carlos when possible
      const passIdx = idx('PASS');
      let passed = false;
      if (passIdx >= 0 && turns % 3 !== 0) {
        await cmds.nth(passIdx).click();
        await sleep(150);
        const target = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'CARLOS SANTANA' });
        if (await target.count()) {
          await target.first().click();
          passed = true;
        } else {
          const back = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'BACK' });
          if (await back.count()) await back.first().click();
        }
      }
      if (!passed) {
        const labels2 = await page.locator('#commands .cmd:not([disabled])').allTextContents();
        const shootIdx = labels2.findIndex(t => t.includes('SHOOT'));
        const specialIdx = labels2.findIndex(t => t.includes('SPECIAL'));
        const dribbleIdx = labels2.findIndex(t => t.includes('DRIBBLE'));
        if (shootIdx >= 0) await page.locator('#commands .cmd:not([disabled])').nth(shootIdx).click();
        else if (specialIdx >= 0) await page.locator('#commands .cmd:not([disabled])').nth(specialIdx).click();
        else if (dribbleIdx >= 0) await page.locator('#commands .cmd:not([disabled])').nth(dribbleIdx).click();
        else await page.locator('#commands .cmd:not([disabled])').first().click();
      }
    } else {
      const labels = await cmds.allTextContents();
      const pressIdx = labels.findIndex(t => t.includes('PRESS'));
      await cmds.nth(pressIdx >= 0 ? pressIdx : 0).click();
    }
    turns++;
    await sleep(180);
  }

  await page.waitForTimeout(800);
  const score = await page.locator('#result-score').textContent().catch(() => '?');
  const title = await page.locator('#result-title').textContent().catch(() => '?');
  const body = await page.locator('#result-body').textContent().catch(() => '?');
  console.log(`\n=== ${label} ===`);
  console.log('RESULT:', title, score);
  console.log(body.replace(/\s+/g, ' ').slice(0, 300));
  await page.screenshot({ path: `/home/runner/work/PlayGround/PlayGround/screenshots/${label}-result.png` });
  return { title, score };
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1024, height: 768 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGE EXCEPTION:', e.message); });
  page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('favicon')) console.log('CONSOLE ERROR:', m.text()); });
  await page.goto(URL, { waitUntil: 'networkidle' });
  await playChapter(page, 0, 'ch1');
  await browser.close();
  if (errors.length) { console.log('ERRORS', errors); process.exit(1); }
})();

