const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const URL = 'http://localhost:3002';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

async function stopMeter(page) {
  await page.waitForSelector('#meter-layer:not(.hidden)', { timeout: 4000 });
  const deadline = Date.now() + 6000;
  while (Date.now() < deadline) {
    const hidden = await page.evaluate(() => document.getElementById('meter-layer').classList.contains('hidden'));
    if (hidden) return;
    const left = await page.evaluate(() => parseFloat(document.getElementById('meter-marker').style.left || '0'));
    if (Math.abs(left - 50) < 7) {
      await page.keyboard.press('Space');
      await sleep(900);
      return;
    }
    await sleep(16);
  }
  await page.keyboard.press('Space');
  await sleep(900);
}

async function clickIfVisible(page, selector, timeout = 1200) {
  try {
    const el = page.locator(selector).first();
    if (await el.isVisible({ timeout })) { await el.click(); return true; }
  } catch {}
  return false;
}

async function skipStory(page) {
  if (await page.locator('#screen-story:not(.hidden)').isVisible().catch(() => false)) {
    await clickIfVisible(page, '#story-skip');
    await sleep(200);
  }
}

async function playChapter(page, chapterIndex, label) {
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.getByRole('button', { name: 'NEW STORY' }).click();
  await page.locator('.chapter').nth(chapterIndex).click();
  await sleep(300);
  await skipStory(page);
  await sleep(300);
  // training
  if (await page.locator('.training-card').first().isVisible().catch(() => false)) {
    await page.locator('.training-card').nth(1).click();
    await sleep(800);
    await skipStory(page);
  }
  await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 8000 });
  await sleep(600);

  let turns = 0;
  for (let i = 0; i < 400; i++) {
    if (await page.locator('#screen-result:not(.hidden)').isVisible().catch(() => false)) break;
    if (await page.locator('#screen-match.hidden').isVisible().catch(() => false)) break;

    // announce modal (halftime / extra time)
    const modal = page.locator('#screen-match .overlay .modal');
    if (await modal.isVisible().catch(() => false)) {
      const btn = modal.locator('button').last();
      if (await btn.isVisible().catch(() => false)) { await btn.click(); await sleep(600); continue; }
    }

    // special move cut-in: wait it out
    if (await page.locator('#cutin-layer:not(.hidden)').isVisible().catch(() => false)) {
      await sleep(300);
      continue;
    }

    // meter
    if (await page.locator('#meter-layer:not(.hidden)').isVisible().catch(() => false)) {
      await stopMeter(page);
      continue;
    }

    const cmds = page.locator('#commands .cmd:not([disabled])');
    const count = await cmds.count();
    if (!count) { await sleep(120); continue; }

    const possession = await page.locator('#possession-label').textContent().catch(() => '');
    const yours = possession.includes('YOUR');

    if (yours) {
      const labels = await cmds.allTextContents();
      const idx = (txt) => labels.findIndex(t => t.includes(txt));
      const passIdx = idx('PASS');
      let passed = false;
      if (passIdx >= 0 && turns % 3 !== 0) {
        await cmds.nth(passIdx).click();
        await sleep(180);
        const target = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'CARLOS SANTANA' });
        if (await target.count()) {
          await target.first().click();
          passed = true;
        } else {
