      }
      const labels2 = await page.locator('#commands .cmd:not([disabled])').allTextContents();
      const shootIdx = labels2.findIndex(t => t.includes('SHOOT'));
      const specialIdx = labels2.findIndex(t => t.includes('SPECIAL'));
      const dribbleIdx = labels2.findIndex(t => t.includes('DRIBBLE'));
      const all = page.locator('#commands .cmd:not([disabled])');
      if (shootIdx >= 0) await all.nth(shootIdx).click();
      else if (specialIdx >= 0) await all.nth(specialIdx).click();
      else if (dribbleIdx >= 0) await all.nth(dribbleIdx).click();
      else await all.first().click();
    } else {
      const labels = await cmds.allTextContents();
      const pressIdx = labels.findIndex(t => t.includes('PRESS'));
      await cmds.nth(pressIdx >= 0 ? pressIdx : 0).click();
    }
    turns++;
    await sleep(400);
  }

