const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const URL = 'http://localhost:3002';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const SHOT = (name) => `/home/runner/work/PlayGround/PlayGround/screenshots/${name}.png`;

async function visible(page, sel) {
  return page.locator(sel).first().isVisible().catch(() => false);
}

async function gameInfo(page) {
  return page.evaluate(() => {
    const s = window.__cs?.state;
    if (!s) return null;
    const carrier = s.carrier ? (() => {
      for (const t of s.teams) {
        const p = t.players.find(pl => pl.id === s.carrier);
        if (p) return { name: p.name, team: p.team, x: p.x, y: p.y, stamina: p.stamina };
      }
      return null;
    })() : null;
    return {
      possession: s.possession,
      playerTeam: s.playerTeam,
      carrier,
      minute: s.minute,
      score: s.score,
      finished: s.finished
    };
  });
}

async function stopMeter(page) {
  const deadline = Date.now() + 6000;
  while (Date.now() < deadline) {
    if (await page.evaluate(() => document.getElementById('meter-layer').classList.contains('hidden'))) return;
    const left = await page.evaluate(() => parseFloat(document.getElementById('meter-marker').style.left || '0'));
    if (Math.abs(left - 50) < 8) {
      await page.keyboard.press('Space');
      await sleep(900);
      return;
    }
    await sleep(14);
  }
  await page.keyboard.press('Space');
  await sleep(900);
}

async function skipStory(page) {
  for (let i = 0; i < 4; i++) {
    if (!(await visible(page, '#screen-story:not(.hidden)'))) return;
    const skip = page.locator('#story-skip');
    if (await skip.isVisible().catch(() => false)) {
      await skip.click().catch(() => {});
      await sleep(250);
      return;
    }
    await sleep(150);
  }
}

async function pickSpecial(page, wantShot) {
  const special = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'SPECIAL' });
  if (!(await special.count())) return false;
  await special.first().click();
  await sleep(180);
  const moves = page.locator('#commands .cmd:not([disabled])');
  const labels = await moves.allTextContents();
  const shotNames = ['STRIKE', 'CYCLONE'];
  const dribNames = ['TURN', 'HEEL'];
  const names = wantShot ? shotNames : dribNames;
  let idx = labels.findIndex(t => names.some(n => t.includes(n)));
  if (idx < 0 && !wantShot) idx = labels.findIndex(t => shotNames.some(n => t.includes(n)));
  if (idx < 0) {
    const back = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'BACK' });
    if (await back.count()) await back.first().click();
    return false;
  }
  await moves.nth(idx).click();
  return true;
}

async function playMatch(page, label) {
  let turns = 0;
  for (let i = 0; i < 3000; i++) {
    if (await visible(page, '#screen-result:not(.hidden)')) break;

    const modal = page.locator('#screen-match .overlay:not(.hidden) .modal');
    if (await modal.isVisible().catch(() => false)) {
      const btn = modal.locator('button').last();
      if (await btn.isVisible().catch(() => false)) { await btn.click(); await sleep(600); continue; }
    }
    if (await visible(page, '#cutin-layer:not(.hidden)')) { await sleep(250); continue; }
    if (await visible(page, '#meter-layer:not(.hidden)')) { await stopMeter(page); continue; }
    if (await visible(page, '#pause-layer:not(.hidden)')) {
      await page.locator('#btn-resume').click(); await sleep(200); continue;
    }

    const cmds = page.locator('#commands .cmd:not([disabled])');
    if (!(await cmds.count())) { await sleep(120); continue; }
    const info = await gameInfo(page);
    const yours = info && info.possession === info.playerTeam;

    if (yours) {
      const labels = await cmds.allTextContents();
      const idx = (t) => labels.findIndex(x => x.includes(t));
      const carrier = info?.carrier;
      const isCarlos = carrier?.name === 'CARLOS SANTANA';
      const nearGoal = carrier ? (100 - carrier.y) <= 45 : false;

      if (!isCarlos) {
        const passIdx = idx('PASS');
        if (passIdx >= 0) {
          await cmds.nth(passIdx).click();
          await sleep(160);
          const target = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'CARLOS SANTANA' });
          if (await target.count()) { await target.first().click(); turns++; await sleep(350); continue; }
          const back = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'BACK' });
          if (await back.count()) await back.first().click();
          await sleep(120);
        }
        const labels2 = await page.locator('#commands .cmd:not([disabled])').allTextContents();
        const all = page.locator('#commands .cmd:not([disabled])');
        const d = labels2.findIndex(t => t.includes('DRIBBLE'));
        if (d >= 0) await all.nth(d).click(); else await all.first().click();
        turns++; await sleep(350); continue;
      }

      // Carlos has the ball
      if (nearGoal) {
        const shotReady = labels.some(t => t.includes('SHOOT'));
        const useSpecial = turns % 2 === 0;
        if (shotReady && useSpecial && await pickSpecial(page, true)) {
          turns++; await sleep(400); continue;
        }
        if (shotReady) {
          const all = page.locator('#commands .cmd:not([disabled])');
          const s = labels.findIndex(t => t.includes('SHOOT'));
          await all.nth(s).click();
          turns++; await sleep(400); continue;
        }
      }
      // advance with special dribble or dribble
      if (turns % 3 === 0 && await pickSpecial(page, false)) {
        turns++; await sleep(350); continue;
      }
      const all = page.locator('#commands .cmd:not([disabled])');
      const labels3 = await all.allTextContents();
      const d = labels3.findIndex(t => t.includes('DRIBBLE'));
      if (d >= 0) await all.nth(d).click();
      else {
        const s = labels3.findIndex(t => t.includes('SHOOT'));
        if (s >= 0) await all.nth(s).click();
        else await all.first().click();
      }
    } else {
      const labels = await cmds.allTextContents();
      const pressIdx = labels.findIndex(t => t.includes('PRESS'));
      await cmds.nth(pressIdx >= 0 ? pressIdx : 0).click();
    }
    turns++;
    await sleep(350);
  }

  await page.waitForTimeout(700);
  const info = await page.evaluate(() => ({
    title: document.getElementById('result-title').textContent,
    home: document.getElementById('result-home').textContent,
    away: document.getElementById('result-away').textContent,
    body: document.getElementById('result-body').textContent.replace(/\s+/g, ' ').trim(),
    match: window.__cs?.state ? {
      finished: window.__cs.state.finished,
      extra: window.__cs.state.extra,
      suddenDeath: window.__cs.state.suddenDeath,
      half: window.__cs.state.half,
      minute: window.__cs.state.minute,
      shots: window.__cs.state.stats.shots
    } : null
  }));
  console.log(`\n=== ${label} ===`);
  console.log(`${info.title} ${info.home}:${info.away}`, info.match);
  console.log(info.body.slice(0, 220));
  await page.screenshot({ path: SHOT(`${label}-result`) });
  return info;
}

async function main() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1024, height: 768 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGE EXCEPTION:', e.message, '\n', e.stack); });
  page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('favicon')) console.log('CONSOLE ERROR:', m.text()); });

  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.getByRole('button', { name: 'NEW STORY' }).click();
  await sleep(300);

  for (let ch = 0; ch < 4; ch++) {
    console.log(`\n--- starting chapter ${ch + 1} ---`);
    if (!(await visible(page, '#screen-map:not(.hidden)'))) {
      console.log('not on map, screen =', await page.evaluate(() => window.__cs?.screen));
    }
    await page.locator(`.chapter[data-index="${ch}"]`).click();
    await sleep(400);
    await skipStory(page);
    await sleep(300);

    if (await visible(page, '.training-card')) {
      await page.locator('.training-card').nth(1).click();
      await sleep(900);
    }
    await skipStory(page);
    await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 10000 });
    await sleep(500);

    let result = await playMatch(page, `ch${ch + 1}`);

    let tries = 0;
    while (!result.title.includes('VICTORY') && tries < 2) {
      tries++;
      const retry = page.locator('#btn-result-retry');
      if (!(await retry.isVisible().catch(() => false))) break;
      console.log(`retrying chapter ${ch + 1} (${result.title})`);
      await retry.click();
      await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 10000 });
      await sleep(400);
      result = await playMatch(page, `ch${ch + 1}-retry${tries}`);
    }
    if (!result.title.includes('VICTORY')) {
      console.log('COULD NOT WIN CHAPTER', ch + 1);
      await page.locator('#btn-result-main').click();
      await sleep(400);
      break;
    }

    await page.locator('#btn-result-main').click();
    await sleep(400);

    for (let i = 0; i < 8; i++) {
      if (await visible(page, '#screen-story:not(.hidden)')) { await skipStory(page); await sleep(250); continue; }
      break;
    }
    if (ch < 3) {
      await page.waitForSelector('#screen-map:not(.hidden)', { timeout: 10000 });
      console.log('map reached; save chapter =', await page.evaluate(() => window.__cs.save.chapter));
      await page.screenshot({ path: SHOT(`map-after-ch${ch + 1}`) });
    }
  }

  await sleep(500);
  for (let i = 0; i < 12; i++) {
    if (await visible(page, '#screen-story:not(.hidden)')) { await skipStory(page); await sleep(250); continue; }
    if (await visible(page, '#screen-result:not(.hidden)')) break;
    await sleep(250);
  }
  await page.waitForTimeout(800);
  const final = await page.evaluate(() => ({
    screen: window.__cs?.screen,
    title: document.getElementById('result-title').textContent,
    eyebrow: document.getElementById('result-eyebrow').textContent,
    body: document.getElementById('result-body').textContent.replace(/\s+/g, ' ').trim(),
    save: window.__cs ? {
      chapter: window.__cs.save.chapter,
      cleared: window.__cs.save.cleared,
      trained: window.__cs.save.trained,
      trophies: window.__cs.save.trophies,
      completed: window.__cs.save.completed,
      moves: window.__cs.save.moves,
      stats: window.__cs.save.stats
    } : null
  }));
  console.log('\n=== ENDING ===');
  console.log(JSON.stringify(final, null, 1));
  await page.screenshot({ path: SHOT('ending') });

  if (await visible(page, '#btn-result-main')) {
    await page.locator('#btn-result-main').click();
    await sleep(600);
  }
  console.log('after ending screen =', await page.evaluate(() => window.__cs?.screen));
  await page.screenshot({ path: SHOT('map-complete') });

  await browser.close();
  console.log('\nERRORS:', errors.length ? errors : 'none');
  if (errors.length) process.exit(1);
}

main().catch((e) => { console.error(e); process.exit(1); });

