];

function carlosOf(state) {
  return state.teams[state.playerTeam].players.find(p => p.name === 'CARLOS SANTANA');
}

function attackPolicy(state, timing) {
  const c = playerById(state, state.carrier);
  const carlos = carlosOf(state);
  const isCarlos = c.id === carlos.id;

  if (!isCarlos) {
    const opts = passOptions(state);
    const toCarlos = opts.find(p => p.id === carlos.id);
    if (toCarlos) return { type: 'pass', targetId: carlos.id };
    // otherwise dribble with the best dribbler
    return { type: 'dribble' };
  }

  const moves = availableMoves(state).filter(m => m.usable);
  const shots = moves.filter(m => m.move.type === 'shot');
  if (canShoot(state)) {
    if (shots.length && c.stamina >= shots[0].move.cost) return { type: 'special', moveId: shots[0].id };
    return { type: 'shoot' };
  }
  const dribbles = moves.filter(m => m.move.type === 'dribble');
  if (dribbles.length) return { type: 'special', moveId: dribbles[0].id };
  return { type: 'dribble' };
}

function defensePolicy(state, timing) {
  const c = playerById(state, state.carrier);
  // block when the opponent is close to our goal, press otherwise
  if (c && c.y >= 62) return 'block';
  return 'press';
}

function simulate(chapter, save, timing, games) {
  const tally = { win: 0, draw: 0, loss: 0, gf: 0, ga: 0, shots: 0, goals: [] };
  for (let i = 0; i < games; i++) {
    const state = createMatch({
      home: chapter.match.home(save),
      away: chapter.match.away(),
      minutes: chapter.match.minutes,
      goldenGoal: chapter.match.goldenGoal,
      difficulty: chapter.match.difficulty,
      playerTeam: 0
    });
    let guard = 0;
    while (!state.finished && guard++ < 500) {
      if (state.phase === 'halftime') { resumeSecondHalf(state); continue; }
      if (state.phase === 'extra') { resumeExtraTime(state); continue; }
      let plan;
      if (state.possession === state.playerTeam) {
        const action = attackPolicy(state, timing);
        plan = beginAttack(state, action);
        if (!plan) { state.minute++; continue; }
        resolvePlan(state, plan, timing);
      } else {
        plan = beginDefense(state, defensePolicy(state, timing));
        if (!plan) { state.minute++; continue; }
        resolvePlan(state, plan, timing);
      }
    }
    const [h, a] = state.score;
    if (h > a) tally.win++; else if (h === a) tally.draw++; else tally.loss++;
    tally.gf += h; tally.ga += a; tally.shots += state.stats.shots[0];
    if (i < 12) tally.goals.push(`${h}-${a}${state.extra ? (state.suddenDeath ? 'sd' : 'x') : ''}`);
  }
  return tally;
}

const games = Number(process.argv[2] || 200);
const timing = Number(process.argv[3] || 0.9);
CHAPTERS.forEach((ch, ci) => {
  const t = simulate(ch, saves[ci], timing, games);
  const pct = (n) => Math.round((n / games) * 100);
  console.log(`${ch.id} ${ch.match.minutes}min timing=${timing} win=${pct(t.win)}% draw=${pct(t.draw)}% loss=${pct(t.loss)}% gf/g=${(t.gf / games).toFixed(2)} ga/g=${(t.ga / games).toFixed(2)} shots/g=${(t.shots / games).toFixed(1)}`);
  console.log('  ', t.goals.join(' '));
});

