const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

const URL = 'http://localhost:3002';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const SHOT = (name) => `/home/runner/work/PlayGround/PlayGround/screenshots/${name}.png`;

const SAVE = {
  version: 1,
  chapter: 3,
  stats: { shot: 15, dribble: 14, pass: 11, tackle: 8, speed: 12, stamina: 116 },
  moves: ['santanaTurn', 'gauchoHeel', 'sambaStrike', 'goldenCyclone'],
  cleared: ['ch1', 'ch2', 'ch3'],
  trained: ['ch1', 'ch2', 'ch3'],
  trophies: 0,
  completed: false,
  matches: 3
};

async function visible(page, sel) {
  return page.locator(sel).first().isVisible().catch(() => false);
}

async function info(page) {
  return page.evaluate(() => {
    const s = window.__cs?.state;
    if (!s) return null;
    let carrier = null;
    for (const t of s.teams) {
      const p = t.players.find(pl => pl.id === s.carrier);
      if (p) carrier = { name: p.name, team: p.team, x: p.x, y: p.y, stamina: p.stamina };
    }
    return { poss: s.possession, playerTeam: s.playerTeam, carrier, minute: s.minute, score: s.score, phase: s.phase };
  });
}

async function stopMeter(page) {
  const deadline = Date.now() + 6000;
  while (Date.now() < deadline) {
    if (await page.evaluate(() => document.getElementById('meter-layer').classList.contains('hidden'))) return;
    const left = await page.evaluate(() => parseFloat(document.getElementById('meter-marker').style.left || '0'));
    if (Math.abs(left - 50) < 5) {
      await page.keyboard.press('Space');
      await sleep(900);
      return;
    }
    await sleep(12);
  }
  await page.keyboard.press('Space');
  await sleep(900);
}

async function skipStory(page) {
  for (let i = 0; i < 5; i++) {
    if (!(await visible(page, '#screen-story:not(.hidden)'))) return false;
    const skip = page.locator('#story-skip');
    if (await skip.isVisible().catch(() => false)) {
      await skip.click().catch(() => {});
      await sleep(300);
      return true;
    }
    await sleep(150);
  }
  return false;
}

async function pickMove(page, wantShot) {
  const special = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'SPECIAL' });
  if (!(await special.count())) return false;
  await special.first().click();
  await sleep(180);
  const moves = page.locator('#commands .cmd:not([disabled])');
  const labels = await moves.allTextContents();
  const names = wantShot ? ['CYCLONE', 'STRIKE'] : ['TURN', 'HEEL'];
  const idx = labels.findIndex(t => names.some(n => t.includes(n)));
  if (idx < 0) {
    const back = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'BACK' });
    if (await back.count()) await back.first().click();
    return false;
  }
  await moves.nth(idx).click();
  return true;
}

async function playMatch(page, label, retries = 2) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    let turns = 0;
    for (let i = 0; i < 3000; i++) {
      if (await visible(page, '#screen-result:not(.hidden)')) break;

      const modal = page.locator('#screen-match .overlay:not(.hidden) .modal');
      if (await modal.isVisible().catch(() => false)) {
        console.log('  modal:', (await modal.innerText()).split('\n')[0]);
        const btn = modal.locator('button').last();
        if (await btn.isVisible().catch(() => false)) { await btn.click(); await sleep(650); continue; }
      }
      if (await visible(page, '#cutin-layer:not(.hidden)')) { await sleep(220); continue; }
      if (await visible(page, '#meter-layer:not(.hidden)')) { await stopMeter(page); continue; }
      if (await visible(page, '#pause-layer:not(.hidden)')) {
        await page.locator('#btn-resume').click(); await sleep(200); continue;
      }

      const cmds = page.locator('#commands .cmd:not([disabled])');
      if (!(await cmds.count())) { await sleep(110); continue; }
      const g = await info(page);

      if (g && g.poss === g.playerTeam) {
        const labels = await cmds.allTextContents();
        const all = page.locator('#commands .cmd:not([disabled])');
        const c = g.carrier;
        const isCarlos = c?.name === 'CARLOS SANTANA';
        const nearGoal = c ? (100 - c.y) >= 45 : false;

        if (!isCarlos) {
          const passIdx = labels.findIndex(t => t.includes('PASS'));
          if (passIdx >= 0) {
            await all.nth(passIdx).click();
            await sleep(150);
            const target = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'CARLOS SANTANA' });
            if (await target.count()) { await target.first().click(); turns++; await sleep(320); continue; }
            const back = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'BACK' });
            if (await back.count()) await back.first().click();
            await sleep(100);
          }
          const labels2 = await page.locator('#commands .cmd:not([disabled])').allTextContents();
          const a2 = page.locator('#commands .cmd:not([disabled])');
          const d = labels2.findIndex(t => t.includes('DRIBBLE'));
          if (d >= 0) await a2.nth(d).click(); else await a2.first().click();
          turns++; await sleep(320); continue;
        }

        if (nearGoal) {
          const labels2 = await page.locator('#commands .cmd:not([disabled])').allTextContents();
          const canSpecial = labels2.some(t => t.includes('SPECIAL'));
          if (canSpecial && await pickMove(page, true)) { turns++; await sleep(380); continue; }
          const a2 = page.locator('#commands .cmd:not([disabled])');
          const s = labels2.findIndex(t => t.includes('SHOOT'));
          if (s >= 0) { await a2.nth(s).click(); turns++; await sleep(380); continue; }
        }

        if (turns % 2 === 0 && await pickMove(page, false)) { turns++; await sleep(320); continue; }
        const labels3 = await page.locator('#commands .cmd:not([disabled])').allTextContents();
        const a3 = page.locator('#commands .cmd:not([disabled])');
        const d = labels3.findIndex(t => t.includes('DRIBBLE'));
        if (d >= 0) await a3.nth(d).click();
        else {
          const s = labels3.findIndex(t => t.includes('SHOOT'));
          if (s >= 0) await a3.nth(s).click(); else await a3.first().click();
        }
      } else {
        const c = g?.carrier;
        const labels = await cmds.allTextContents();
        const block = c && c.y >= 62;
        const want = block ? 'BLOCK' : 'PRESS';
        let idx = labels.findIndex(t => t.includes(want));
        if (idx < 0) idx = labels.findIndex(t => t.includes('PRESS'));
        await cmds.nth(idx >= 0 ? idx : 0).click();
      }
      turns++;
      await sleep(320);
    }

    await page.waitForTimeout(600);
    const r = await page.evaluate(() => ({
      title: document.getElementById('result-title').textContent,
      home: document.getElementById('result-home').textContent,
      away: document.getElementById('result-away').textContent,
      body: document.getElementById('result-body').textContent.replace(/\s+/g, ' ').trim(),
      state: window.__cs?.state ? {
        extra: window.__cs.state.extra,
        suddenDeath: window.__cs.state.suddenDeath,
        minute: window.__cs.state.minute,
        shots: window.__cs.state.stats.shots,
        score: window.__cs.state.score
      } : null
    }));
    console.log(`\n=== ${label} attempt ${attempt + 1} ===`);
    console.log(`${r.title} ${r.home}:${r.away}`, r.state);
    console.log(r.body.slice(0, 180));
    await page.screenshot({ path: SHOT(`${label}-attempt${attempt + 1}`) });

    if (r.title.includes('VICTORY')) return r;
    const retry = page.locator('#btn-result-main');
    if (attempt < retries && (await retry.innerText()).includes('TRY AGAIN')) {
      console.log('  retrying...');
      await retry.click();
      await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 10000 });
      await sleep(400);
      continue;
    }
    return r;
  }
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1024, height: 768 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGE EXCEPTION:', e.message, '\n', e.stack); });
  page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('favicon')) console.log('CONSOLE ERROR:', m.text()); });

  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.evaluate((s) => localStorage.setItem('carlos_santana_super_striker_v1', JSON.stringify(s)), SAVE);
  await page.reload();
  await page.locator('#btn-continue').click();
  await sleep(400);
  console.log('map screen:', await page.evaluate(() => window.__cs.screen));
  await page.locator('.chapter[data-index="3"]').click();
  await sleep(400);
  await skipStory(page);
  await sleep(300);
  if (await visible(page, '.training-card')) {
    await page.locator('.training-card').nth(0).click();
    await sleep(900);
  }
  await skipStory(page);
  await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 10000 });
  await sleep(400);

  const result = await playMatch(page, 'ch4');
  if (!result.title.includes('VICTORY')) {
    console.log('FAILED TO WIN CH4');
    await browser.close();
    process.exit(1);
  }

  await page.locator('#btn-result-main').click();
  await sleep(500);
  console.log('after result click, screen =', await page.evaluate(() => window.__cs.screen));

  for (let i = 0; i < 30; i++) {
    if (await visible(page, '#screen-story:not(.hidden)')) { await skipStory(page); await sleep(300); continue; }
    if (await visible(page, '#screen-result:not(.hidden)')) break;
    await sleep(250);
  }
  await page.waitForTimeout(800);

  const end = await page.evaluate(() => ({
    screen: window.__cs?.screen,
    title: document.getElementById('result-title').textContent,
    eyebrow: document.getElementById('result-eyebrow').textContent,
    body: document.getElementById('result-body').textContent.replace(/\s+/g, ' ').trim(),
    trophy: !!document.getElementById('ending-trophy'),
    save: window.__cs ? {
      chapter: window.__cs.save.chapter,
      cleared: window.__cs.save.cleared,
      trophies: window.__cs.save.trophies,
      completed: window.__cs.save.completed,
      matches: window.__cs.save.matches
    } : null
  }));
  console.log('\n=== ENDING ===');
  console.log(JSON.stringify(end, null, 1));
  await page.screenshot({ path: SHOT('ending') });

  await page.locator('#btn-result-main').click();
  await sleep(700);
  console.log('after ending button, screen =', await page.evaluate(() => window.__cs.screen));
  await page.screenshot({ path: SHOT('map-complete') });

  await browser.close();
  console.log('\nERRORS:', errors.length ? errors : 'none');
  if (errors.length) process.exit(1);
})().catch((e) => { console.error(e); process.exit(1); });

