const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const SHOT = (n) => `/home/runner/work/PlayGround/PlayGround/screenshots/mobile-${n}.png`;

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGE EXCEPTION:', e.message); });
  page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('favicon')) console.log('CONSOLE ERROR:', m.text()); });

  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await sleep(500);

  const layout = await page.evaluate(() => ({
    inner: [window.innerWidth, window.innerHeight],
    scrollW: document.documentElement.scrollWidth,
    scrollH: document.documentElement.scrollHeight,
    title: document.getElementById('screen-title').getBoundingClientRect().toJSON()
  }));
  console.log('layout', JSON.stringify(layout));
  await page.screenshot({ path: SHOT('title') });

  await page.getByRole('button', { name: 'NEW STORY' }).tap();
  await sleep(400);
  await page.screenshot({ path: SHOT('story') });
  // advance story by tapping the dialogue area
  for (let i = 0; i < 3; i++) {
    if (await page.locator('#screen-story:not(.hidden)').isVisible().catch(() => false)) {
      await page.locator('#story-skip').tap().catch(() => {});
      await sleep(300);
    }
  }
  await sleep(400);

  if (await page.locator('.training-card').first().isVisible().catch(() => false)) {
    await page.screenshot({ path: SHOT('training') });
    await page.locator('.training-card').nth(0).tap();
    await sleep(900);
  }
  for (let i = 0; i < 3; i++) {
    if (await page.locator('#screen-story:not(.hidden)').isVisible().catch(() => false)) {
      await page.locator('#story-skip').tap().catch(() => {});
      await sleep(300);
    }
  }
  await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 10000 });
  await sleep(700);
  await page.screenshot({ path: SHOT('match') });

  // check overflow / element boxes
  const boxes = await page.evaluate(() => {
    const pick = (id) => {
      const el = document.getElementById(id);
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), bottom: Math.round(r.bottom) };
    };
    return {
      inner: [window.innerWidth, window.innerHeight],
      scrollW: document.documentElement.scrollWidth,
      scrollH: document.documentElement.scrollHeight,
      pitch: pick('pitch'),
      commands: pick('commands'),
      pause: pick('btn-pause'),
      matchBar: document.querySelector('.match-bar')?.getBoundingClientRect().toJSON(),
      log: pick('match-log')
    };
  });
  console.log('match boxes', JSON.stringify(boxes, null, 1));

  // tap a command
  const cmds = page.locator('#commands .cmd:not([disabled])');
  console.log('command count', await cmds.count(), await cmds.allTextContents());
  await cmds.first().tap();
  await sleep(300);

  // play a couple of turns, tapping meter
  for (let i = 0; i < 40; i++) {
    if (await page.locator('#meter-layer:not(.hidden)').isVisible().catch(() => false)) {
      await page.locator('#meter-layer').tap({ position: { x: 195, y: 400 } }).catch(() => {});
      await sleep(900);
      continue;
    }
    const c = page.locator('#commands .cmd:not([disabled])');
    if (!(await c.count())) { await sleep(150); continue; }
    await c.first().tap();
    await sleep(350);
  }
  await page.screenshot({ path: SHOT('after-turns') });

  // pause menu
  await page.locator('#btn-pause').tap();
  await sleep(400);
  await page.screenshot({ path: SHOT('pause') });
  const pause = await page.evaluate(() => {
    const el = document.querySelector('#pause-layer .modal');
    const r = el.getBoundingClientRect();
    return { x: r.x, y: r.y, w: r.width, h: r.height, bottom: r.bottom, inner: [innerWidth, innerHeight] };
  });
  console.log('pause modal', JSON.stringify(pause));
  await page.locator('#btn-resume').tap();
  await sleep(300);

  console.log('errors', errors.length ? errors : 'none');
  await browser.close();
  if (errors.length) process.exit(1);
})().catch((e) => { console.error(e); process.exit(1); });

