const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const SHOT = (n) => `/home/runner/work/PlayGround/PlayGround/screenshots/${n}.png`;

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1024, height: 768 } });
  const errors = [];
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGE EXCEPTION:', e.message, e.stack); });
  page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('favicon')) console.log('CONSOLE ERROR:', m.text()); });

  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.getByRole('button', { name: 'NEW STORY' }).click();
  await sleep(300);
  await page.locator('.chapter[data-index="0"]').click();
  await sleep(300);
  await page.locator('#story-skip').click().catch(() => {});
  await sleep(400);
  if (await page.locator('.training-card').first().isVisible().catch(() => false)) {
    await page.locator('.training-card').nth(0).click();
    await sleep(900);
  }
  await page.locator('#story-skip').click().catch(() => {});
  await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 10000 });
  await sleep(500);

  async function forceFinish(score) {
    await page.evaluate((sc) => {
      const s = window.__cs.state;
      s.minutes = 1;
      s.minute = 1;
      s.score = sc;
      if (s.teams[1]) s.teams[1].score = sc[1];
    }, score);
    // pick any command to advance the clock
    const cmds = page.locator('#commands .cmd:not([disabled])');
    if (await cmds.count()) {
      const labels = await cmds.allTextContents();
      let idx = labels.findIndex(t => t.includes('HOLD'));
      if (idx < 0) idx = labels.findIndex(t => t.includes('PRESS'));
      await cmds.nth(idx >= 0 ? idx : 0).click();
    }
    // stop a meter if one appears
    for (let i = 0; i < 20; i++) {
      if (await page.locator('#screen-result:not(.hidden)').isVisible().catch(() => false)) break;
      if (await page.locator('#meter-layer:not(.hidden)').isVisible().catch(() => false)) {
        await page.keyboard.press('Space');
        await sleep(900);
        continue;
      }
      await sleep(150);
    }
  }

  await forceFinish([0, 1]);
  await sleep(700);
  const loss = await page.evaluate(() => ({
    screen: window.__cs.screen,
    title: document.getElementById('result-title').textContent,
    score: `${document.getElementById('result-home').textContent}:${document.getElementById('result-away').textContent}`,
    main: document.getElementById('btn-result-main').textContent,
    mainVisible: !document.getElementById('btn-result-main').classList.contains('hidden'),
    retryHidden: document.getElementById('btn-result-retry').classList.contains('hidden'),
    mapVisible: !document.getElementById('btn-result-map').classList.contains('hidden'),
    mapText: document.getElementById('btn-result-map').textContent
  }));
  console.log('LOSS RESULT', loss);
  await page.screenshot({ path: SHOT('loss-result') });

  // TRY AGAIN -> restart
  await page.locator('#btn-result-main').click();
  await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 10000 });
  await sleep(600);
  const restart = await page.evaluate(() => ({
    screen: window.__cs.screen,
    minute: window.__cs.state?.minute,
    score: window.__cs.state?.score,
    finished: window.__cs.state?.finished
  }));
  console.log('AFTER RETRY', restart);

  // force another loss, then BACK TO MAP -> lose story
  await forceFinish([0, 1]);
  await sleep(700);
  const mapBtn = page.locator('#btn-result-map');
  console.log('map button before click:', await mapBtn.innerText(), await mapBtn.isVisible());
  await mapBtn.click();
  await sleep(500);
  console.log('after map click screen =', await page.evaluate(() => window.__cs.screen));
  await page.screenshot({ path: SHOT('lose-story') });
  // skip lose story
  for (let i = 0; i < 6; i++) {
    if (await page.locator('#screen-story:not(.hidden)').isVisible().catch(() => false)) {
      await page.locator('#story-skip').click().catch(() => {});
      await sleep(300);
      continue;
    }
    break;
  }
  await sleep(500);
  console.log('after lose story screen =', await page.evaluate(() => window.__cs.screen));
  await page.screenshot({ path: SHOT('after-loss-map') });

  console.log('errors', errors.length ? errors : 'none');
  await browser.close();
  if (errors.length) process.exit(1);
})().catch((e) => { console.error(e); process.exit(1); });

