const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const SHOT = (n) => `/home/runner/work/PlayGround/PlayGround/screenshots/${n}.png`;

const SAVE = {
  version: 1, chapter: 3,
  stats: { shot: 16, dribble: 15, pass: 12, tackle: 8, speed: 12, stamina: 120 },
  moves: ['santanaTurn', 'gauchoHeel', 'sambaStrike', 'goldenCyclone'],
  cleared: ['ch1', 'ch2', 'ch3'], trained: ['ch1', 'ch2', 'ch3'],
  trophies: 0, completed: false, matches: 3
};

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1024, height: 768 } });
  const errors = [];
  page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGE EXCEPTION:', e.message); });
  page.on('console', (m) => { if (m.type() === 'error' && !m.text().includes('favicon')) console.log('CONSOLE ERROR:', m.text()); });

  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.evaluate((s) => localStorage.setItem('carlos_santana_super_striker_v1', JSON.stringify(s)), SAVE);
  await page.reload();
  await page.locator('#btn-continue').click();
  await sleep(300);
  await page.locator('.chapter[data-index="3"]').click();
  await sleep(300);
  for (let i = 0; i < 3; i++) {
    if (await page.locator('#screen-story:not(.hidden)').isVisible().catch(() => false)) {
      await page.locator('#story-skip').click().catch(() => {});
      await sleep(300);
    }
  }
  if (await page.locator('.training-card').first().isVisible().catch(() => false)) {
    await page.locator('.training-card').nth(0).click();
    await sleep(900);
  }
  await page.locator('#story-skip').click().catch(() => {});
  await page.waitForSelector('#screen-match:not(.hidden)', { timeout: 10000 });
  await sleep(500);

  // force a 0-0 at the end of regulation
  await page.evaluate(() => {
    const s = window.__cs.state;
    s.minutes = 1; s.minute = 1; s.score = [0, 0];
  });
  const hold = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'HOLD' });
  if (await hold.count()) await hold.first().click();
  else await page.locator('#commands .cmd:not([disabled])').first().click();

  // expect EXTRA TIME modal
  const modal = page.locator('#screen-match .overlay:not(.hidden) .modal');
  await modal.waitFor({ state: 'visible', timeout: 8000 });
  console.log('modal text:', (await modal.innerText()).replace(/\s+/g, ' '));
  await page.screenshot({ path: SHOT('extra-time-modal') });
  await modal.locator('button').last().click();
  await sleep(600);
  console.log('phase after modal:', await page.evaluate(() => ({ phase: window.__cs.state.phase, extra: window.__cs.state.extra, minute: window.__cs.state.minute })));

  // play until result
  for (let i = 0; i < 1200; i++) {
    if (await page.locator('#screen-result:not(.hidden)').isVisible().catch(() => false)) break;
    if (await page.locator('#meter-layer:not(.hidden)').isVisible().catch(() => false)) {
      const deadline = Date.now() + 5000;
      while (Date.now() < deadline) {
        const left = await page.evaluate(() => parseFloat(document.getElementById('meter-marker').style.left || '0'));
        if (Math.abs(left - 50) < 6) break;
        await sleep(12);
      }
      await page.keyboard.press('Space');
      await sleep(900);
      continue;
    }
    const cmds = page.locator('#commands .cmd:not([disabled])');
    if (!(await cmds.count())) { await sleep(120); continue; }
    const g = await page.evaluate(() => {
      const s = window.__cs.state;
      let carrier = null;
      for (const t of s.teams) {
        const p = t.players.find(pl => pl.id === s.carrier);
        if (p) carrier = { name: p.name, y: p.y, stamina: p.stamina };
      }
      return { poss: s.possession, playerTeam: s.playerTeam, carrier, minute: s.minute, score: s.score };
    });
    if (g.poss === g.playerTeam) {
      const labels = await cmds.allTextContents();
      const all = page.locator('#commands .cmd:not([disabled])');
      if (g.carrier?.name === 'CARLOS SANTANA') {
        const near = (100 - g.carrier.y) >= 45;
        const specialIdx = labels.findIndex(t => t.includes('SPECIAL'));
        const shootIdx = labels.findIndex(t => t.includes('SHOOT'));
        if (near && specialIdx >= 0) {
          await all.nth(specialIdx).click();
          await sleep(160);
          const moves = page.locator('#commands .cmd:not([disabled])');
          const ml = await moves.allTextContents();
          const cyc = ml.findIndex(t => t.includes('CYCLONE'));
          const strike = ml.findIndex(t => t.includes('STRIKE'));
          const pick = cyc >= 0 ? cyc : strike;
          if (pick >= 0) await moves.nth(pick).click();
          else {
            const back = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'BACK' });
            if (await back.count()) await back.first().click();
            await sleep(100);
            const a2 = page.locator('#commands .cmd:not([disabled])');
            const l2 = await a2.allTextContents();
            const si = l2.findIndex(t => t.includes('SHOOT'));
            if (si >= 0) await a2.nth(si).click();
          }
        } else if (near && shootIdx >= 0) {
          await all.nth(shootIdx).click();
        } else {
          const d = labels.findIndex(t => t.includes('DRIBBLE'));
          if (d >= 0) await all.nth(d).click(); else await all.first().click();
        }
      } else {
        const p = labels.findIndex(t => t.includes('PASS'));
        if (p >= 0) {
          await all.nth(p).click();
          await sleep(140);
          const target = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'CARLOS SANTANA' });
          if (await target.count()) await target.first().click();
          else {
            const back = page.locator('#commands .cmd:not([disabled])').filter({ hasText: 'BACK' });
            if (await back.count()) await back.first().click();
          }
        } else {
          const d = labels.findIndex(t => t.includes('DRIBBLE'));
          if (d >= 0) await all.nth(d).click(); else await all.first().click();
        }
      }
    } else {
      const labels = await cmds.allTextContents();
      const block = g.carrier && g.carrier.y >= 62;
      let idx = labels.findIndex(t => t.includes(block ? 'BLOCK' : 'PRESS'));
      if (idx < 0) idx = labels.findIndex(t => t.includes('PRESS'));
      await cmds.nth(idx >= 0 ? idx : 0).click();
    }
    await sleep(300);
  }

  await sleep(700);
  const result = await page.evaluate(() => ({
    title: document.getElementById('result-title').textContent,
    eyebrow: document.getElementById('result-eyebrow').textContent,
    score: `${document.getElementById('result-home').textContent}:${document.getElementById('result-away').textContent}`,
    state: { extra: window.__cs.state.extra, suddenDeath: window.__cs.state.suddenDeath, minute: window.__cs.state.minute, finished: window.__cs.state.finished }
  }));
  console.log('GOLDEN GOAL RESULT', result);
  await page.screenshot({ path: SHOT('golden-goal-result') });
  console.log('errors', errors.length ? errors : 'none');
  await browser.close();
  if (errors.length) process.exit(1);
})().catch((e) => { console.error(e); process.exit(1); });

